insert into public.parts(id,section_id,name,display_order) values('d2115786-810b-dbc1-4189-4d054f8f9581','bee41358-7368-5bbb-bb76-e42afe3c1c44','Algebra',10) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d401cdeb-c5b9-896e-ee37-d63a5e8e182c','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"If $5x - 8 = 27$, what is the value of $x$?","options":[{"id":"A","label":"$\\frac{19}{5}$"},{"id":"B","label":"$7$"},{"id":"C","label":"$\\frac{67}{5}$"},{"id":"D","label":"$35$"}]}'::jsonb,1,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'd401cdeb-c5b9-896e-ee37-d63a5e8e182c','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Add 8 to both sides to get $5x = 35$, then divide by 5: $x = 7$. Choice A comes from subtracting 8 instead of adding it ($5x = 19$). Choice C comes from dividing 27 by 5 and then adding 8, which undoes the steps in the wrong order. Choice D is the value of $5x$, not $x$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='d401cdeb-c5b9-896e-ee37-d63a5e8e182c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('28296df2-4c99-6cf1-2049-276a18f701b6','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A climbing gym charges a one-time registration fee of 25 dollars plus 12 dollars for each month of membership. Lena paid a total of 121 dollars for registration and $m$ months of membership. What is the value of $m$?","options":[{"id":"A","label":"$8$"},{"id":"B","label":"$\\frac{121}{12}$"},{"id":"C","label":"$\\frac{73}{6}$"},{"id":"D","label":"$96$"}]}'::jsonb,2,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '28296df2-4c99-6cf1-2049-276a18f701b6','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The total cost is $25 + 12m = 121$. Subtract 25: $12m = 96$. Divide by 12: $m = 8$. Choice B divides the total by 12 and ignores the registration fee. Choice C adds the fee instead of subtracting it ($12m = 146$). Choice D is the cost of the months, $12m$, rather than the number of months."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='28296df2-4c99-6cf1-2049-276a18f701b6') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5572997c-5f93-af2a-fd04-66095d78fde3','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"What value of $x$ satisfies the equation $\\frac{x}{4} + 3 = 9$?","options":[{"id":"A","label":"$\\frac{3}{2}$"},{"id":"B","label":"$24$"},{"id":"C","label":"$33$"},{"id":"D","label":"$48$"}]}'::jsonb,3,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5572997c-5f93-af2a-fd04-66095d78fde3','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Subtract 3 from both sides: $\\frac{x}{4} = 6$. Multiply both sides by 4: $x = 24$. Choice A divides 6 by 4 instead of multiplying. Choice C multiplies 9 by 4 before subtracting 3, which treats the equation as $\\frac{x+3}{4} = 9$. Choice D adds 3 instead of subtracting it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5572997c-5f93-af2a-fd04-66095d78fde3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ef993f7f-773b-d29a-83a0-5202712cdfc6','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"What is the solution to the equation $3(x + 4) = 2x + 19$?","options":[{"id":"A","label":"$\\frac{7}{5}$"},{"id":"B","label":"$7$"},{"id":"C","label":"$15$"},{"id":"D","label":"$31$"}]}'::jsonb,4,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ef993f7f-773b-d29a-83a0-5202712cdfc6','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Distribute: $3x + 12 = 2x + 19$. Subtract $2x$ and 12 from both sides: $x = 7$. Choice C comes from writing $3x + 4$ instead of $3x + 12$ (not distributing the 3 to the 4). Choice A comes from adding $2x$ to $3x$ instead of subtracting, giving $5x = 7$. Choice D comes from adding 12 to 19 instead of subtracting it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ef993f7f-773b-d29a-83a0-5202712cdfc6') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5a13bbb3-0660-f680-e470-afe667179076','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"If $2x + 7 = 15$, what is the value of $6x + 21$?","options":[{"id":"A","label":"$4$"},{"id":"B","label":"$24$"},{"id":"C","label":"$31$"},{"id":"D","label":"$45$"}]}'::jsonb,5,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5a13bbb3-0660-f680-e470-afe667179076','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Notice that $6x + 21 = 3(2x + 7)$. Since $2x + 7 = 15$, the expression equals $3(15) = 45$. (Solving first also works: $x = 4$, and $6(4) + 21 = 45$.) Choice A is the value of $x$, choice B is the value of $6x$, and choice C adds 7 instead of 21."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5a13bbb3-0660-f680-e470-afe667179076') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6e424fe9-24b9-5f2a-a2af-84ea14349f73','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A taxi ride costs 3.50 dollars to start plus 1.25 dollars for each mile driven. A ride cost a total of 16.00 dollars. How many miles long was the ride?","options":[{"id":"A","label":"$10$"},{"id":"B","label":"$12.5$"},{"id":"C","label":"$12.8$"},{"id":"D","label":"$15.6$"}]}'::jsonb,6,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6e424fe9-24b9-5f2a-a2af-84ea14349f73','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Let $m$ be the number of miles. Then $3.50 + 1.25m = 16.00$, so $1.25m = 12.50$ and $m = 10$. Choice B is the cost of the miles, 12.50 dollars, not the number of miles. Choice C divides the total by 1.25 and ignores the 3.50-dollar starting charge. Choice D adds the starting charge instead of subtracting it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6e424fe9-24b9-5f2a-a2af-84ea14349f73') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1d3951b0-82b2-d42b-480b-5f865bf4f40f','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"What value of $x$ is the solution to $7 - 2x = 19$?","options":[{"id":"A","label":"$-13$"},{"id":"B","label":"$-6$"},{"id":"C","label":"$6$"},{"id":"D","label":"$13$"}]}'::jsonb,7,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1d3951b0-82b2-d42b-480b-5f865bf4f40f','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Subtract 7 from both sides: $-2x = 12$. Divide by $-2$: $x = -6$. Choice C ignores the negative sign on $-2x$. Choice A and choice D come from adding 7 to 19 instead of subtracting it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1d3951b0-82b2-d42b-480b-5f865bf4f40f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fdf88a46-3f11-4a00-c074-aa797640fb0f','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"What is the solution to the equation $\\frac{2x - 1}{3} = \\frac{x + 4}{2}$?","options":[{"id":"A","label":"$\\frac{11}{4}$"},{"id":"B","label":"$5$"},{"id":"C","label":"$13$"},{"id":"D","label":"$14$"}]}'::jsonb,8,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fdf88a46-3f11-4a00-c074-aa797640fb0f','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Multiply both sides by 6: $2(2x - 1) = 3(x + 4)$, so $4x - 2 = 3x + 12$ and $x = 14$. Choice B comes from not distributing ($4x - 1 = 3x + 4$). Choice C distributes the 2 to $2x$ but not to $-1$. Choice A cross-multiplies with the wrong denominators, $3(2x - 1) = 2(x + 4)$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fdf88a46-3f11-4a00-c074-aa797640fb0f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a3365396-8407-7d3a-2865-f75ff21f8393','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"In the equation $4(2x - 3) = 8x + k$, $k$ is a constant. For what value of $k$ does the equation have infinitely many solutions?","options":[{"id":"A","label":"$-12$"},{"id":"B","label":"$-3$"},{"id":"C","label":"$3$"},{"id":"D","label":"$12$"}]}'::jsonb,9,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a3365396-8407-7d3a-2865-f75ff21f8393','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The left side is $8x - 12$. The equation $8x - 12 = 8x + k$ is true for every $x$ exactly when $k = -12$. Any other value of $k$ gives no solution. Choice B uses $-3$ from inside the parentheses without multiplying by 4. Choice C changes the sign of that $-3$, and choice D changes the sign of $-12$; both give no solution."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a3365396-8407-7d3a-2865-f75ff21f8393') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('60af2b1d-6b63-1e31-72ba-9ebfb20e1e57','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"How many solutions does the equation $3(2x + 5) = 6x + 15$ have?","options":[{"id":"A","label":"Exactly one"},{"id":"B","label":"Exactly two"},{"id":"C","label":"Infinitely many"},{"id":"D","label":"None"}]}'::jsonb,10,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '60af2b1d-6b63-1e31-72ba-9ebfb20e1e57','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Distributing gives $6x + 15 = 6x + 15$, which is true for every value of $x$, so the equation has infinitely many solutions. Choice A is tempting if you stop after seeing a single $x$ term on each side, but subtracting $6x$ leaves $15 = 15$ rather than a value of $x$. A linear equation can never have exactly two solutions (choice B), and choice D would require a false statement such as $15 = 12$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='60af2b1d-6b63-1e31-72ba-9ebfb20e1e57') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dee32b97-98b2-0dbf-b329-bda283a5dfd4','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Caterer P charges a 150-dollar setup fee plus 18 dollars per guest. Caterer Q charges a 90-dollar setup fee plus 22 dollars per guest. For how many guests will the two caterers charge the same total amount?","options":[{"id":"A","label":"$1.5$"},{"id":"B","label":"$6$"},{"id":"C","label":"$15$"},{"id":"D","label":"$60$"}]}'::jsonb,11,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'dee32b97-98b2-0dbf-b329-bda283a5dfd4','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Set the costs equal: $150 + 18g = 90 + 22g$. Subtract $18g$ and 90 from both sides: $60 = 4g$, so $g = 15$. Choice D stops at $60 = 4g$ without dividing. Choice A divides 60 by $22 + 18$, adding the per-guest prices instead of subtracting them. Choice B divides the total of the setup fees by the total of the per-guest prices, which does not compare the two caterers."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='dee32b97-98b2-0dbf-b329-bda283a5dfd4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8e75d3a2-1234-243e-a07c-20e44f48710b','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"What value of $x$ satisfies $\\frac{3}{4}(x - 8) = \\frac{1}{2}x + 1$?","options":[{"id":"A","label":"$\\frac{7}{4}$"},{"id":"B","label":"$20$"},{"id":"C","label":"$28$"},{"id":"D","label":"$36$"}]}'::jsonb,12,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8e75d3a2-1234-243e-a07c-20e44f48710b','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Distribute: $\\frac{3}{4}x - 6 = \\frac{1}{2}x + 1$. Subtract $\\frac{1}{2}x$ and add 6: $\\frac{1}{4}x = 7$, so $x = 28$. Choice D forgets to multiply the 8 by $\\frac{3}{4}$. Choice B moves both constants with the wrong signs, writing $\\frac{1}{4}x = 6 - 1 = 5$. Choice A divides 7 by 4 instead of multiplying."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8e75d3a2-1234-243e-a07c-20e44f48710b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bf2153ca-1fbd-1c43-8e98-548b842b3cde','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The formula $F = \\frac{9}{5}C + 32$ converts a temperature of $C$ degrees Celsius to $F$ degrees Fahrenheit. A weather station records a temperature of 50 degrees Fahrenheit. What is this temperature in degrees Celsius?","options":[{"id":"A","label":"$10$"},{"id":"B","label":"$18$"},{"id":"C","label":"$\\frac{162}{5}$"},{"id":"D","label":"$122$"}]}'::jsonb,13,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'bf2153ca-1fbd-1c43-8e98-548b842b3cde','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Substitute $F = 50$: $50 = \\frac{9}{5}C + 32$. Subtract 32 to get $18 = \\frac{9}{5}C$, then multiply by $\\frac{5}{9}$: $C = 10$. Choice B stops after subtracting 32. Choice C multiplies 18 by $\\frac{9}{5}$ instead of dividing. Choice D substitutes 50 for $C$ instead of $F$, converting in the wrong direction."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='bf2153ca-1fbd-1c43-8e98-548b842b3cde') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3a6189ce-7fd4-266d-13d7-99794c63f4e8','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"What is the solution to $5(x - 2) - 3(x + 1) = 11$?","options":[{"id":"A","label":"$7$"},{"id":"B","label":"$9$"},{"id":"C","label":"$11$"},{"id":"D","label":"$12$"}]}'::jsonb,14,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3a6189ce-7fd4-266d-13d7-99794c63f4e8','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Distribute carefully: $5x - 10 - 3x - 3 = 11$, so $2x - 13 = 11$, $2x = 24$, and $x = 12$. Choice B results from $-3(x + 1) = -3x + 3$, a sign error. Choice A results from not distributing either coefficient to the constants. Choice C distributes the 5 but not the $-3$ to the 1."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3a6189ce-7fd4-266d-13d7-99794c63f4e8') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ddd4817b-e9f3-f332-1585-46b104505d22','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"An online store sells a jacket at 80% of its original price $p$, in dollars, and then adds a 6-dollar shipping charge. A customer pays 54 dollars in total. The equation $0.8p + 6 = 54$ represents this situation. What was the original price of the jacket, in dollars?","options":[{"id":"A","label":"$\\frac{192}{5}$"},{"id":"B","label":"$\\frac{123}{2}$"},{"id":"C","label":"$60$"},{"id":"D","label":"$240$"}]}'::jsonb,15,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ddd4817b-e9f3-f332-1585-46b104505d22','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Subtract 6: $0.8p = 48$. Divide by 0.8: $p = 60$. Choice A multiplies 48 by 0.8 instead of dividing. Choice B divides 54 by 0.8 before subtracting the shipping charge. Choice D divides by 0.2, the discount rate, instead of 0.8, the fraction of the price that is paid."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ddd4817b-e9f3-f332-1585-46b104505d22') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a5b948e9-24f1-2bd2-99e1-7a2c6e031ece','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The equation $\\frac{3x + p}{4} = \\frac{x}{2} + 5$, where $p$ is a constant, has the solution $x = 6$. What is the value of $p$?","options":[{"id":"A","label":"$-1$"},{"id":"B","label":"$2$"},{"id":"C","label":"$14$"},{"id":"D","label":"$26$"}]}'::jsonb,16,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a5b948e9-24f1-2bd2-99e1-7a2c6e031ece','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Substitute $x = 6$: $\\frac{18 + p}{4} = 3 + 5 = 8$. Multiply by 4: $18 + p = 32$, so $p = 14$. Choice A multiplies only the $\\frac{x}{2}$ term by 4, writing $18 + p = 12 + 5$. Choice B drops the $\\frac{x}{2}$ term, solving $\\frac{18 + p}{4} = 5$. Choice D uses 6 instead of $\\frac{6}{2} = 3$ for $\\frac{x}{2}$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a5b948e9-24f1-2bd2-99e1-7a2c6e031ece') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dc148e5b-e691-1bd3-aec0-c24b5348c94c','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"In the equation $\\frac{k}{3}(6x - 9) = 4x + c$, $k$ and $c$ are constants. If the equation has infinitely many solutions, what is the value of $c$?"}'::jsonb,17,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-017","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'dc148e5b-e691-1bd3-aec0-c24b5348c94c','{"accepted":["-6"]}'::jsonb,'{"feedback":{"explanation":"Distribute: $\\frac{k}{3}(6x - 9) = 2kx - 3k$. For the equation $2kx - 3k = 4x + c$ to hold for all $x$, the coefficients of $x$ must match and the constants must match: $2k = 4$, so $k = 2$, and $c = -3k = -6$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='dc148e5b-e691-1bd3-aec0-c24b5348c94c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1a9e9112-daf0-c814-821f-1f3497bef8ab','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"In the equation $a(x + 3) - 2x = 4x + 9$, $a$ is a constant. For which value of $a$ does the equation have no solution?","options":[{"id":"A","label":"$-6$"},{"id":"B","label":"$2$"},{"id":"C","label":"$3$"},{"id":"D","label":"$6$"}]}'::jsonb,18,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1a9e9112-daf0-c814-821f-1f3497bef8ab','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Expand and collect terms: $ax + 3a - 2x = 4x + 9$, so $(a - 6)x = 9 - 3a$. There is no solution when the coefficient of $x$ is 0 but the constant is not: $a = 6$ gives $0 = -9$, which is false. Choice C makes the constant $9 - 3a$ zero, which gives the single solution $x = 0$. Choice A ($a = -6$) has the wrong sign, and choice B ($a = 2$) adds the coefficients $-2$ and 4 instead of moving $4x$ across the equal sign; both leave a nonzero coefficient $a - 6$, so each gives exactly one solution."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1a9e9112-daf0-c814-821f-1f3497bef8ab') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('53bf20e7-609c-f3c3-ad4b-e785994db404','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Right now, Ana is 3 times as old as her cousin. In 12 years, Ana will be twice as old as her cousin will be then. How old, in years, is Ana now?","options":[{"id":"A","label":"$12$"},{"id":"B","label":"$24$"},{"id":"C","label":"$36$"},{"id":"D","label":"$48$"}]}'::jsonb,19,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '53bf20e7-609c-f3c3-ad4b-e785994db404','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Let $c$ be the cousin''s current age, so Ana is $3c$. In 12 years: $3c + 12 = 2(c + 12)$, so $3c + 12 = 2c + 24$ and $c = 12$. Ana is $3(12) = 36$ years old. Choice A is the cousin''s current age. Choice B is the cousin''s age in 12 years. Choice D is Ana''s age in 12 years rather than now."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='53bf20e7-609c-f3c3-ad4b-e785994db404') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b09c48bd-2fcb-8d93-3b96-698704dcae15','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"What is the solution to the equation $\\frac{x + 2}{3} - \\frac{2x - 1}{4} = \\frac{1}{6}$?"}'::jsonb,20,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-020","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b09c48bd-2fcb-8d93-3b96-698704dcae15','{"accepted":["9/2","4.5"]}'::jsonb,'{"feedback":{"explanation":"Multiply every term by 12: $4(x + 2) - 3(2x - 1) = 2$. Expand: $4x + 8 - 6x + 3 = 2$, so $-2x + 11 = 2$, $-2x = -9$, and $x = \\frac{9}{2}$, or 4.5. A frequent error is writing $-3(2x - 1)$ as $-6x - 3$, which gives $x = \\frac{3}{2}$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b09c48bd-2fcb-8d93-3b96-698704dcae15') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('97280980-e5e1-afb0-6a3b-e73d913b042a','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"In the equation $4(px - 3) = 12x - 3q$, $p$ and $q$ are constants. The equation has infinitely many solutions. What is the value of $p + q$?","options":[{"id":"A","label":"$-1$"},{"id":"B","label":"$7$"},{"id":"C","label":"$9$"},{"id":"D","label":"$16$"}]}'::jsonb,21,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '97280980-e5e1-afb0-6a3b-e73d913b042a','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The left side is $4px - 12$. For infinitely many solutions, $4px - 12$ and $12x - 3q$ must be identical: $4p = 12$ gives $p = 3$, and $-12 = -3q$ gives $q = 4$. So $p + q = 7$. Choice A uses $q = -4$, a sign error. Choice D adds the visible coefficients 4 and 12, and choice C subtracts 3 from 12 without solving for either constant."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='97280980-e5e1-afb0-6a3b-e73d913b042a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2a2b8b32-f931-8586-6274-7536ca629bc3','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"In the equation $\\frac{3}{5}(10x - 15) - 2(ax + 1) = 4$, $a$ is a constant. If the equation has no solution, what is the value of $a$?"}'::jsonb,22,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_one_variable","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin1v-022","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2a2b8b32-f931-8586-6274-7536ca629bc3','{"accepted":["3"]}'::jsonb,'{"feedback":{"explanation":"Expand: $6x - 9 - 2ax - 2 = 4$, so $(6 - 2a)x - 11 = 4$, or $(6 - 2a)x = 15$. The equation has no solution only when the coefficient of $x$ is 0, because then it reads $0 = 15$. So $6 - 2a = 0$ and $a = 3$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2a2b8b32-f931-8586-6274-7536ca629bc3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f3e713a8-5acb-1530-6257-e07bac48f564','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The function $f$ is defined by $f(x) = 4x - 9$. What is the value of $f(5)$?","options":[{"id":"A","label":"$-4$"},{"id":"B","label":"$\\frac{7}{2}$"},{"id":"C","label":"$11$"},{"id":"D","label":"$29$"}]}'::jsonb,23,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f3e713a8-5acb-1530-6257-e07bac48f564','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Substitute 5 for $x$: $f(5) = 4(5) - 9 = 20 - 9 = 11$. Choice D adds 9 instead of subtracting it. Choice B solves $4x - 9 = 5$, which finds the input that gives an output of 5. Choice A adds the input to $-9$ without multiplying by 4."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f3e713a8-5acb-1530-6257-e07bac48f564') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4726a5d9-c20c-7a99-8b81-242ea7504fc9','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"For the linear function $f$, the table shows three values of $x$ and their corresponding values of $f(x)$. What is the slope of the graph of $y = f(x)$ in the xy-plane?","table":{"headers":["x","f(x)"],"rows":[["1","7"],["3","13"],["5","19"]]},"options":[{"id":"A","label":"$\\frac{1}{3}$"},{"id":"B","label":"$3$"},{"id":"C","label":"$4$"},{"id":"D","label":"$6$"}]}'::jsonb,24,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4726a5d9-c20c-7a99-8b81-242ea7504fc9','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"From $x = 1$ to $x = 3$, $f(x)$ increases from 7 to 13. The slope is $\\frac{13 - 7}{3 - 1} = \\frac{6}{2} = 3$. Choice D is the change in $f(x)$ between rows, but $x$ also changes by 2. Choice C is the y-intercept, $f(0) = 7 - 3 = 4$. Choice A inverts the ratio."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4726a5d9-c20c-7a99-8b81-242ea7504fc9') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('352c3f1a-58a9-36bd-d48f-436d9de9f038','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A plumber uses the function $C(h) = 65h + 40$ to find the total charge, in dollars, for a job that takes $h$ hours. What is the best interpretation of 40 in this context?","options":[{"id":"A","label":"The charge for each hour of work"},{"id":"B","label":"The total charge for a job that takes 1 hour"},{"id":"C","label":"The number of hours the plumber works on a typical job"},{"id":"D","label":"A fixed charge that does not depend on the number of hours"}]}'::jsonb,25,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '352c3f1a-58a9-36bd-d48f-436d9de9f038','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"When $h = 0$, $C(0) = 40$, so 40 dollars is charged regardless of time: a fixed fee. Choice A describes 65, the coefficient of $h$. Choice C confuses a charge with a number of hours. Choice B would be $C(1) = 105$ dollars, not 40."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='352c3f1a-58a9-36bd-d48f-436d9de9f038') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('536e8eb9-0e89-5221-4f19-c167a6e66ec1','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"The function $g$ is defined by $g(x) = -2x + 7$. For what value of $x$ does $g(x) = -5$?"}'::jsonb,26,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-004","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '536e8eb9-0e89-5221-4f19-c167a6e66ec1','{"accepted":["6"]}'::jsonb,'{"feedback":{"explanation":"Set $-2x + 7 = -5$. Subtract 7: $-2x = -12$. Divide by $-2$: $x = 6$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='536e8eb9-0e89-5221-4f19-c167a6e66ec1') on conflict do nothing;
