9.8 83.8L210.9 81.6L211.9 79.4L213.0 77.1L214.1 74.9L215.1 72.7L216.2 70.5L217.2 68.3L218.2 66.1L219.3 63.9L220.3 61.6L221.4 59.4L222.4 57.2L223.5 55.0L224.5 52.8L225.6 50.6L226.6 48.4L227.7 46.1L228.8 43.9L229.8 41.7L230.9 39.5L231.9 37.3L232.9 35.1L234.0 32.9L235.0 30.6L236.1 28.4L237.2 26.2L238.2 24.0\" stroke=\"#2563eb\" stroke-width=\"2\" fill=\"none\"/><circle cx=\"150.0\" cy=\"210.0\" r=\"3\" fill=\"currentColor\"/><circle cx=\"225.6\" cy=\"50.6\" r=\"3\" fill=\"currentColor\"/></svg>","options":[{"id":"A","label":"$y = \\frac{1}{2}x + 2$"},{"id":"B","label":"$y = 3x + 2$"},{"id":"C","label":"$y = 2x - 2$"},{"id":"D","label":"$y = 2x + 2$"}]}'::jsonb,27,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '216d8480-0088-fc36-03de-88d69b0bb2f8','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The y-intercept is 2. The slope is $\\frac{8 - 2}{3 - 0} = 2$. So $y = 2x + 2$. Choice A inverts the slope (run over rise). Choice C has the wrong sign for the intercept. Choice B uses the x-coordinate 3 as the slope."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='216d8480-0088-fc36-03de-88d69b0bb2f8') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ef1f49e2-24c4-3d35-c272-2653e7da1f9c','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"A bike-share service charges according to the function $C(m) = 2.4m + 3$, where $C(m)$ is the cost, in dollars, of a ride that lasts $m$ half-hour periods. What is the cost, in dollars, of a ride that lasts 15 half-hour periods?"}'::jsonb,28,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-006","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ef1f49e2-24c4-3d35-c272-2653e7da1f9c','{"accepted":["39"]}'::jsonb,'{"feedback":{"explanation":"Substitute $m = 15$: $C(15) = 2.4(15) + 3 = 36 + 3 = 39$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ef1f49e2-24c4-3d35-c272-2653e7da1f9c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7ec18a6d-ed2c-d334-8813-5cccdd35dfff','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A line in the xy-plane has a slope of 3 and passes through the point $(2, 5)$. What is the y-coordinate of the line''s y-intercept?","options":[{"id":"A","label":"$-1$"},{"id":"B","label":"$3$"},{"id":"C","label":"$5$"},{"id":"D","label":"$11$"}]}'::jsonb,29,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '7ec18a6d-ed2c-d334-8813-5cccdd35dfff','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Use $y = 3x + b$ with $(2, 5)$: $5 = 3(2) + b$, so $b = -1$. Choice C is the y-coordinate of the given point, not the intercept. Choice D adds $3 \\cdot 2$ instead of subtracting it. Choice B is the slope."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='7ec18a6d-ed2c-d334-8813-5cccdd35dfff') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8e5745c8-09c9-e044-db06-12866d8b08e1','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"If $f(x) = \\frac{x}{3} + 2$, what is $f(12)$?","options":[{"id":"A","label":"$4$"},{"id":"B","label":"$\\frac{14}{3}$"},{"id":"C","label":"$6$"},{"id":"D","label":"$38$"}]}'::jsonb,30,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8e5745c8-09c9-e044-db06-12866d8b08e1','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"$f(12) = \\frac{12}{3} + 2 = 4 + 2 = 6$. Choice B divides $12 + 2$ by 3, treating the function as $\\frac{x + 2}{3}$. Choice A forgets to add 2. Choice D multiplies by 3 instead of dividing."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8e5745c8-09c9-e044-db06-12866d8b08e1') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('16872594-9897-f5af-3ea0-e2a84b49b214','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"For the linear function $f$, $f(2) = 5$ and $f(6) = 17$. Which equation defines $f$?","options":[{"id":"A","label":"$f(x) = \\frac{1}{3}x + \\frac{13}{3}$"},{"id":"B","label":"$f(x) = 3x + 5$"},{"id":"C","label":"$f(x) = 2x + 1$"},{"id":"D","label":"$f(x) = 3x - 1$"}]}'::jsonb,31,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '16872594-9897-f5af-3ea0-e2a84b49b214','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The slope is $\\frac{17 - 5}{6 - 2} = 3$. Then $5 = 3(2) + b$, so $b = -1$, and $f(x) = 3x - 1$. Choice B uses 5 as the y-intercept, but 5 is the output at $x = 2$, not $x = 0$. Choice C fits $f(2) = 5$ only. Choice A inverts the slope."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='16872594-9897-f5af-3ea0-e2a84b49b214') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('26913be7-b8e0-abef-d2b8-3a911d1e5f1a','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The height, in centimeters, of a burning candle $t$ hours after it is lit is modeled by $h(t) = 30 - 1.5t$. According to the model, how many hours after it is lit will the candle be 9 centimeters tall?","options":[{"id":"A","label":"$14$"},{"id":"B","label":"$16.5$"},{"id":"C","label":"$20$"},{"id":"D","label":"$21$"}]}'::jsonb,32,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '26913be7-b8e0-abef-d2b8-3a911d1e5f1a','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Set $30 - 1.5t = 9$. Subtract 30: $-1.5t = -21$, so $t = 14$. Choice B is $h(9)$, the height after 9 hours, which answers a different question. Choice C is the time until the candle burns down completely ($h(t) = 0$). Choice D is the number of centimeters burned, $30 - 9$, not the number of hours."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='26913be7-b8e0-abef-d2b8-3a911d1e5f1a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('59c6d6b4-16fa-1042-6e50-2c60d005d390','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"During a dry season, the volume of water in a reservoir, in millions of liters, is modeled by $w(t) = 1{,}250 - 35t$, where $t$ is the number of days since the start of the season. What is the best interpretation of 35 in this context?","options":[{"id":"A","label":"The reservoir held 35 million liters at the start of the season."},{"id":"B","label":"The reservoir will be empty after 35 days."},{"id":"C","label":"The volume of water decreases by 35% each day."},{"id":"D","label":"The volume of water decreases by 35 million liters each day."}]}'::jsonb,33,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '59c6d6b4-16fa-1042-6e50-2c60d005d390','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"35 is the coefficient of $t$: each additional day reduces $w(t)$ by 35 million liters, a constant rate of decrease. Choice A describes the initial volume, which is $w(0) = 1{,}250$. Choice B is false: the model reaches 0 when $t = \\frac{1250}{35} \\approx 35.7$ days, which is not what 35 represents. Choice C describes exponential decay; a linear model changes by a constant amount, not a constant percent."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='59c6d6b4-16fa-1042-6e50-2c60d005d390') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6fcd7d64-79a0-10d3-5f5b-0212f842efbd','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The table shows three points on the graph of a linear function in the xy-plane. Which equation represents this function?","table":{"headers":["x","y"],"rows":[["-2","11"],["0","7"],["4","-1"]]},"options":[{"id":"A","label":"$y = 2x + 7$"},{"id":"B","label":"$y = -2x + 11$"},{"id":"C","label":"$y = -\\frac{1}{2}x + 7$"},{"id":"D","label":"$y = -2x + 7$"}]}'::jsonb,34,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6fcd7d64-79a0-10d3-5f5b-0212f842efbd','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The point $(0, 7)$ gives the y-intercept 7. From $(0, 7)$ to $(4, -1)$, the slope is $\\frac{-1 - 7}{4 - 0} = -2$. So $y = -2x + 7$. Check: $-2(-2) + 7 = 11$. Choice A has the wrong sign of the slope. Choice C inverts the slope. Choice B uses the first y-value, 11, as the intercept even though it corresponds to $x = -2$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6fcd7d64-79a0-10d3-5f5b-0212f842efbd') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('73ad6e67-df1c-95a6-a9f1-1a583508d29b','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The function $f$ is defined by $f(x) = ax + 3$, where $a$ is a constant. If $f(4) = -9$, what is the value of $a$?","options":[{"id":"A","label":"$-3$"},{"id":"B","label":"$-\\frac{9}{4}$"},{"id":"C","label":"$-\\frac{3}{2}$"},{"id":"D","label":"$3$"}]}'::jsonb,35,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '73ad6e67-df1c-95a6-a9f1-1a583508d29b','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Substitute: $4a + 3 = -9$, so $4a = -12$ and $a = -3$. Choice C adds 3 instead of subtracting it ($4a = -6$). Choice B ignores the constant term. Choice D has the wrong sign."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='73ad6e67-df1c-95a6-a9f1-1a583508d29b') on conflict do nothing;
