2 259.6L219.3 261.2L220.3 262.9L221.4 264.5L222.4 266.1L223.5 267.8L224.5 269.4L225.6 271.0L226.6 272.6L227.7 274.2L228.8 275.9L229.8 277.5L230.9 279.1L231.9 280.8L232.9 282.4L234.0 284.0L235.0 285.6L236.1 287.2L237.2 288.9L238.2 290.5L239.2 292.1L240.3 293.8L241.3 295.4L242.4 297.0L243.5 298.6L244.5 300.2L245.5 301.9L246.6 303.5L247.7 305.1L248.7 306.8L249.8 308.4L250.8 310.0L251.8 311.6L252.9 313.2L253.9 314.9L255.0 316.5L256.1 318.1L257.1 319.8L258.1 321.4L259.2 323.0L260.2 324.6L261.3 326.2L262.4 327.9L263.4 329.5L264.4 331.1L265.5 332.8L266.5 334.4L267.6 336.0\" stroke=\"#2563eb\" stroke-width=\"2\" fill=\"none\"/><circle cx=\"99.6\" cy=\"76.0\" r=\"3\" fill=\"currentColor\"/><circle cx=\"200.4\" cy=\"232.0\" r=\"3\" fill=\"currentColor\"/></svg>","options":[{"id":"A","label":"$-\\frac{3}{2}$"},{"id":"B","label":"$-\\frac{2}{3}$"},{"id":"C","label":"$1$"},{"id":"D","label":"$\\frac{3}{2}$"}]}'::jsonb,36,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f2230496-220c-e500-1e54-572650049fe3','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Slope is the change in $y$ divided by the change in $x$: $\\frac{-2 - 4}{2 - (-2)} = \\frac{-6}{4} = -\\frac{3}{2}$. Choice B divides the change in $x$ by the change in $y$. Choice D drops the negative sign, though the line falls from left to right. Choice C is the y-intercept of the line."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f2230496-220c-e500-1e54-572650049fe3') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3f1d9803-2a95-5439-bc6d-71f33bacde1d','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The function $f$ is defined by $f(x) = 5x - 1$. The function $h$ is defined by $h(x) = f(x + 2)$. Which equation defines $h$?","options":[{"id":"A","label":"$h(x) = 5x + 1$"},{"id":"B","label":"$h(x) = 7x - 1$"},{"id":"C","label":"$h(x) = 5x + 11$"},{"id":"D","label":"$h(x) = 5x + 9$"}]}'::jsonb,37,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3f1d9803-2a95-5439-bc6d-71f33bacde1d','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Replace $x$ with $x + 2$ in $f$: $h(x) = 5(x + 2) - 1 = 5x + 10 - 1 = 5x + 9$. Choice A adds 2 to the output, $f(x) + 2$, instead of to the input. Choice C forgets to subtract 1. Choice B adds 2 to the slope."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3f1d9803-2a95-5439-bc6d-71f33bacde1d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('44f93f6a-9e11-d694-95ae-57abf7e8d0af','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A bakery models its weekly revenue, in dollars, with $R(n) = 12.5n + 300$, where $n$ is the number of cakes sold that week. According to the model, by how many dollars does the revenue increase when the number of cakes sold increases by 10?","options":[{"id":"A","label":"$\\frac{25}{2}$"},{"id":"B","label":"$125$"},{"id":"C","label":"$310$"},{"id":"D","label":"$425$"}]}'::jsonb,38,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '44f93f6a-9e11-d694-95ae-57abf7e8d0af','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Each additional cake adds 12.5 dollars, so 10 more cakes add $10 \\times 12.5 = 125$ dollars. Choice A is the increase for one cake. Choice D is $R(10)$, the total revenue for 10 cakes, which includes the 300-dollar constant. Choice C adds 10 to the constant term."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='44f93f6a-9e11-d694-95ae-57abf7e8d0af') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c3fbc837-911c-8197-d9d6-7be648f7b843','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"In the xy-plane, a line with slope $-\\frac{3}{4}$ passes through the points $(-3, 7)$ and $(5, k)$. What is the value of $k$?"}'::jsonb,39,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-017","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c3fbc837-911c-8197-d9d6-7be648f7b843','{"accepted":["1"]}'::jsonb,'{"feedback":{"explanation":"The slope condition is $\\frac{k - 7}{5 - (-3)} = -\\frac{3}{4}$, so $\\frac{k - 7}{8} = -\\frac{3}{4}$ and $k - 7 = -6$. Thus $k = 1$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c3fbc837-911c-8197-d9d6-7be648f7b843') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('56a3518c-73aa-0e6b-9f03-5a8426d21a8c','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"For the linear function $f$, $f(3) = f(1) + 8$ and $f(0) = -2$. What is the value of $f(5)$?"}'::jsonb,40,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-018","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '56a3518c-73aa-0e6b-9f03-5a8426d21a8c','{"accepted":["18"]}'::jsonb,'{"feedback":{"explanation":"From $x = 1$ to $x = 3$, the output increases by 8 while the input increases by 2, so the slope is $\\frac{8}{2} = 4$. With $f(0) = -2$, $f(x) = 4x - 2$, so $f(5) = 20 - 2 = 18$. A common error is to use 8 as the slope, giving 38."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='56a3518c-73aa-0e6b-9f03-5a8426d21a8c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('93fbc904-4c7f-09da-b89d-7a476c1ae3de','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The function $f$ is defined by $f(x) = kx + 6$, where $k$ is a constant. In the xy-plane, the graph of $y = f(x)$ has an x-intercept at $(4, 0)$. What is the value of $f(-2)$?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$6$"},{"id":"C","label":"$\\frac{22}{3}$"},{"id":"D","label":"$9$"}]}'::jsonb,41,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '93fbc904-4c7f-09da-b89d-7a476c1ae3de','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Since $f(4) = 0$: $4k + 6 = 0$, so $k = -\\frac{3}{2}$. Then $f(-2) = -\\frac{3}{2}(-2) + 6 = 3 + 6 = 9$. Choice A is $f(2)$, which you get by dropping the negative sign on the input. Choice B is $f(0)$, the y-intercept. Choice C uses $k = -\\frac{4}{6}$, dividing the intercepts in the wrong order."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='93fbc904-4c7f-09da-b89d-7a476c1ae3de') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e6cb9669-c3bb-6529-13a5-c68091133c04','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"For the linear function $f$, $f(x + 1) - f(x) = -4$ for all values of $x$, and $f(2) = 10$. Which equation defines $f$?","options":[{"id":"A","label":"$f(x) = -4x + 2$"},{"id":"B","label":"$f(x) = -4x + 10$"},{"id":"C","label":"$f(x) = 4x + 2$"},{"id":"D","label":"$f(x) = -4x + 18$"}]}'::jsonb,42,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e6cb9669-c3bb-6529-13a5-c68091133c04','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"$f(x + 1) - f(x) = -4$ says the output drops by 4 whenever the input increases by 1, so the slope is $-4$. Then $10 = -4(2) + b$ gives $b = 18$. Choice A subtracts 8 from 10 instead of adding. Choice C uses slope 4. Choice B treats $f(2) = 10$ as the y-intercept."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e6cb9669-c3bb-6529-13a5-c68091133c04') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9eb0e104-39af-92e5-172e-cc19fb4a9c2b','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A phone''s battery charge decreases at a constant rate while a video plays. At 1:00 p.m. the charge is 86%, and at 3:30 p.m. it is 61%. If the charge continues to decrease at the same rate, at what time will the charge be 11%?","options":[{"id":"A","label":"6:00 p.m."},{"id":"B","label":"7:00 p.m."},{"id":"C","label":"8:30 p.m."},{"id":"D","label":"10:00 p.m."}]}'::jsonb,43,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9eb0e104-39af-92e5-172e-cc19fb4a9c2b','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"From 1:00 to 3:30 is 2.5 hours, and the charge falls by $86 - 61 = 25$ percentage points, so it falls 10 points per hour. Falling from 86% to 11% is 75 points, which takes $\\frac{75}{10} = 7.5$ hours after 1:00 p.m., or 8:30 p.m. Choice A measures the 50-point drop from 61% but adds the time to 1:00 p.m. instead of 3:30 p.m. Choice B treats the interval as 2 hours (12.5 points per hour), and choice D treats it as 3 hours."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9eb0e104-39af-92e5-172e-cc19fb4a9c2b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('38b0e64a-6a20-8ece-df15-0796735c3f26','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"For the linear function $f$, $f(4) = 2f(1)$ and $f(7) = 15$. What is the value of $f(10)$?"}'::jsonb,44,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-linfn-022","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '38b0e64a-6a20-8ece-df15-0796735c3f26','{"accepted":["20"]}'::jsonb,'{"feedback":{"explanation":"Write $f(x) = mx + b$. The condition $f(4) = 2f(1)$ gives $4m + b = 2(m + b)$, so $b = 2m$. Then $f(7) = 7m + 2m = 9m = 15$, so $m = \\frac{5}{3}$ and $b = \\frac{10}{3}$. Finally $f(10) = \\frac{50}{3} + \\frac{10}{3} = 20$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='38b0e64a-6a20-8ece-df15-0796735c3f26') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b1bda32f-6e4a-72c8-9b9d-9b8c98ea2512','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Which point $(x, y)$ lies on the graph of $2x + 3y = 18$ in the xy-plane?","options":[{"id":"A","label":"$(2, 5)$"},{"id":"B","label":"$(6, 1)$"},{"id":"C","label":"$(4, 3)$"},{"id":"D","label":"$(3, 4)$"}]}'::jsonb,45,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b1bda32f-6e4a-72c8-9b9d-9b8c98ea2512','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Substitute each point: $2(3) + 3(4) = 6 + 12 = 18$, so $(3, 4)$ is on the line. For $(4, 3)$, the coordinates are swapped and give $8 + 9 = 17$. For $(2, 5)$: $4 + 15 = 19$. For $(6, 1)$: $12 + 3 = 15$. Choice A, choice C and choice B do not satisfy the equation."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b1bda32f-6e4a-72c8-9b9d-9b8c98ea2512') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6bc1c134-736e-6b3d-ce1b-02afd44e8e73','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"A florist sells roses for 3 dollars each and tulips for 2 dollars each. One morning the florist''s sales of these two flowers totaled 60 dollars, and 12 roses were sold. How many tulips were sold that morning?"}'::jsonb,46,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6bc1c134-736e-6b3d-ce1b-02afd44e8e73','{"accepted":["12"]}'::jsonb,'{"feedback":{"explanation":"Let $t$ be the number of tulips. Then $3(12) + 2t = 60$, so $36 + 2t = 60$, $2t = 24$, and $t = 12$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6bc1c134-736e-6b3d-ce1b-02afd44e8e73') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('79507c95-81d9-ddca-6c20-d1558fd9e300','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"What is the y-intercept of the graph of $4x - 2y = 10$ in the xy-plane?","options":[{"id":"A","label":"$(0, -10)$"},{"id":"B","label":"$(0, 5)$"},{"id":"C","label":"$(0, \\frac{5}{2})$"},{"id":"D","label":"$(0, -5)$"}]}'::jsonb,47,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '79507c95-81d9-ddca-6c20-d1558fd9e300','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Set $x = 0$: $-2y = 10$, so $y = -5$. The y-intercept is $(0, -5)$. Choice B ignores the negative coefficient of $y$. Choice C uses the x-intercept value $\\frac{5}{2}$, found by setting $y = 0$. Choice A uses the constant 10 without dividing by $-2$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='79507c95-81d9-ddca-6c20-d1558fd9e300') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4e2202c5-563a-d404-c45b-0c0c894f7790','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"What is the slope of the graph of $3x + 4y = 12$ in the xy-plane?","options":[{"id":"A","label":"$-\\frac{4}{3}$"},{"id":"B","label":"$-\\frac{3}{4}$"},{"id":"C","label":"$\\frac{3}{4}$"},{"id":"D","label":"$3$"}]}'::jsonb,48,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4e2202c5-563a-d404-c45b-0c0c894f7790','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Solve for $y$: $4y = -3x + 12$, so $y = -\\frac{3}{4}x + 3$. The slope is $-\\frac{3}{4}$. Choice C forgets that $3x$ changes sign when moved to the other side. Choice A inverts the ratio. Choice D is the y-intercept."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4e2202c5-563a-d404-c45b-0c0c894f7790') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8e8c8b2f-60d2-ca5f-ca2b-3e4c4148d6e0','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Priya has a 40-dollar gift card. She buys $n$ notebooks for 2.50 dollars each and $p$ pens for 1.25 dollars each, using exactly the full value of the card, so $2.5n + 1.25p = 40$. If she buys 10 notebooks, how many pens does she buy?","options":[{"id":"A","label":"$6$"},{"id":"B","label":"$12$"},{"id":"C","label":"$22$"},{"id":"D","label":"$24$"}]}'::jsonb,49,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8e8c8b2f-60d2-ca5f-ca2b-3e4c4148d6e0','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Substitute $n = 10$: $25 + 1.25p = 40$, so $1.25p = 15$ and $p = 12$. Choice D subtracts 10 (the number of notebooks) rather than their cost of 25 dollars. Choice C subtracts 10 after dividing. Choice A divides the remaining 15 dollars by the notebook price instead of the pen price."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8e8c8b2f-60d2-ca5f-ca2b-3e4c4148d6e0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e633aaba-f774-a605-0568-a16a182f255c','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The graph shows a line in the xy-plane that crosses the axes at $(0, 4)$ and $(6, 0)$. Which equation represents the line?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 300 270\" width=\"300\" height=\"270\" role=\"img\" aria-label=\"A line crossing the y-axis at (0, 4) and the x-axis at (6, 0)\" font-family=\"sans-serif\" font-size=\"10\"><title>A line crossing the y-axis at (0, 4) and the x-axis at (6, 0)</title><path d=\"M24.0 246.0V24.0M49.2 246.0V24.0M74.4 246.0V24.0M99.6 246.0V24.0M124.8 246.0V24.0M150.0 246.0V24.0M175.2 246.0V24.0M200.4 246.0V24.0M225.6 246.0V24.0M250.8 246.0V24.0M276.0 246.0V24.0M24.0 246.0H276.0M24.0 221.3H276.0M24.0 196.7H276.0M24.0 172.0H276.0M24.0 147.3H276.0M24.0 122.7H276.0M24.0 98.0H276.0M24.0 73.3H276.0M24.0 48.7H276.0M24.0 24.0H276.0\" stroke=\"currentColor\" stroke-opacity=\"0.18\" stroke-width=\"1\" fill=\"none\"/><path d=\"M24.0 172.0H276.0M74.4 246.0V24.0\" stroke=\"currentColor\" stroke-width=\"1.4\" fill=\"none\"/><text x=\"280.0\" y=\"176.0\" fill=\"currentColor\" font-style=\"italic\" font-size=\"12\">x</text><text x=\"70.4\" y=\"16.0\" fill=\"currentColor\" font-style=\"italic\" font-size=\"12\">y</text><text x=\"24.0\" y=\"184.0\" text-anchor=\"middle\" fill=\"currentColor\">-2</text><text x=\"49.2\" y=\"184.0\" text-anchor=\"middle\" fill=\"currentColor\">-1</text><text x=\"99.6\" y=\"184.0\" text-anchor=\"middle\" fill=\"currentColor\">1</text><text x=\"124.8\" y=\"184.0\" text-anchor=\"middle\" fill=\"currentColor\">2</text><text x=\"150.0\" y=\"184.0\" text-anchor=\"middle\" fill=\"currentColor\">3</text><text x=\"175.2\" y=\"184.0\" text-anchor=\"middle\" fill=\"currentColor\">4</text><text x=\"200.4\" y=\"184.0\" text-anchor=\"middle\" fill=\"currentColor\">5</text><text x=\"225.6\" y=\"184.0\" t