label":"$3x + 2y = 12$"},{"id":"C","label":"$4x + 6y = 12$"},{"id":"D","label":"$2x + 3y = 12$"}]}'::jsonb,50,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e633aaba-f774-a605-0568-a16a182f255c','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Check both intercepts: $2(0) + 3(4) = 12$ and $2(6) + 3(0) = 12$, so $2x + 3y = 12$ works. Choice B swaps the coefficients and gives intercepts $(4, 0)$ and $(0, 6)$. Choice C uses the intercepts as coefficients and gives intercepts $(3, 0)$ and $(0, 2)$. Choice A gives a line with a positive slope."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e633aaba-f774-a605-0568-a16a182f255c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f25ee86e-1416-51d0-f8fc-97b36628c7bd','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"In the xy-plane, the graph of $y = -2x + 9$ crosses the x-axis at the point $(a, 0)$. What is the value of $a$?"}'::jsonb,51,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-007","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f25ee86e-1416-51d0-f8fc-97b36628c7bd','{"accepted":["9/2","4.5"]}'::jsonb,'{"feedback":{"explanation":"At the x-intercept, $y = 0$: $0 = -2a + 9$, so $2a = 9$ and $a = \\frac{9}{2}$, or 4.5."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f25ee86e-1416-51d0-f8fc-97b36628c7bd') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e79b4999-f5eb-d055-2328-5cd4594f45db','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Which of the following equations has a graph in the xy-plane that is parallel to the graph of $y = 3x - 1$?","options":[{"id":"A","label":"$y = 3x + 5$"},{"id":"B","label":"$y = \\frac{1}{3}x + 4$"},{"id":"C","label":"$y = -3x - 1$"},{"id":"D","label":"$y = -\\frac{1}{3}x - 1$"}]}'::jsonb,52,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e79b4999-f5eb-d055-2328-5cd4594f45db','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Parallel lines have equal slopes. The given line has slope 3, and $y = 3x + 5$ also has slope 3 (with a different intercept, so the lines are distinct). Choice C and choice B change the sign or take the reciprocal of the slope, and choice D has the slope of a perpendicular line."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e79b4999-f5eb-d055-2328-5cd4594f45db') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6d6db337-5dab-f0d5-a8b5-b972b479fc12','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Line $k$ in the xy-plane has equation $2x - 5y = 10$. Line $m$ is perpendicular to line $k$. What is the slope of line $m$?","options":[{"id":"A","label":"$-\\frac{5}{2}$"},{"id":"B","label":"$-\\frac{2}{5}$"},{"id":"C","label":"$\\frac{2}{5}$"},{"id":"D","label":"$\\frac{5}{2}$"}]}'::jsonb,53,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6d6db337-5dab-f0d5-a8b5-b972b479fc12','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Rewrite line $k$: $-5y = -2x + 10$, so $y = \\frac{2}{5}x - 2$, with slope $\\frac{2}{5}$. A perpendicular slope is the negative reciprocal, $-\\frac{5}{2}$. Choice D is the reciprocal without the sign change. Choice C is the slope of $k$ itself, which describes a parallel line. Choice B changes the sign but does not take the reciprocal."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6d6db337-5dab-f0d5-a8b5-b972b479fc12') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fd94472c-2022-d940-cbd8-992b38e577a0','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A theater sells adult tickets for 14 dollars each and child tickets for 9 dollars each. On Saturday the theater''s ticket revenue was 2,310 dollars, which is represented by the equation $14a + 9c = 2{,}310$. What does $9c$ represent in this equation?","options":[{"id":"A","label":"The number of child tickets sold"},{"id":"B","label":"The number of child tickets sold for every adult ticket"},{"id":"C","label":"The price of one child ticket, in dollars"},{"id":"D","label":"The revenue, in dollars, from child tickets"}]}'::jsonb,54,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fd94472c-2022-d940-cbd8-992b38e577a0','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"$c$ is the number of child tickets, and each one costs 9 dollars, so $9c$ is the total revenue from child tickets. Choice A describes $c$ alone. Choice C describes the coefficient 9 alone. Choice B describes a ratio that the equation does not give."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fd94472c-2022-d940-cbd8-992b38e577a0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b632e41e-b412-025f-93f7-a3cd71dcea23','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A line in the xy-plane passes through the points $(1, 4)$ and $(5, -4)$. Which equation represents the line?","options":[{"id":"A","label":"$2x + y = 6$"},{"id":"B","label":"$x + 2y = 9$"},{"id":"C","label":"$2x - y = -2$"},{"id":"D","label":"$x - 2y = -7$"}]}'::jsonb,55,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b632e41e-b412-025f-93f7-a3cd71dcea23','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The slope is $\\frac{-4 - 4}{5 - 1} = -2$, so $y - 4 = -2(x - 1)$, which gives $y = -2x + 6$, or $2x + y = 6$. Both points check: $2 + 4 = 6$ and $10 - 4 = 6$. Choice B has slope $-\\frac{1}{2}$ (the reciprocal) and contains only $(1, 4)$. Choice C has slope 2, the wrong sign, and contains only $(1, 4)$. Choice D contains $(1, 4)$ but has slope $\\frac{1}{2}$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b632e41e-b412-025f-93f7-a3cd71dcea23') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('45a1a5a3-d2ae-dea1-a80b-98ace881e72b','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"In the xy-plane, where does the graph of $\\frac{x}{4} + \\frac{y}{6} = 1$ intersect the y-axis?","options":[{"id":"A","label":"$(0, 4)$"},{"id":"B","label":"$(0, 6)$"},{"id":"C","label":"$(0, \\frac{3}{2})$"},{"id":"D","label":"$(0, \\frac{2}{3})$"}]}'::jsonb,56,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '45a1a5a3-d2ae-dea1-a80b-98ace881e72b','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"On the y-axis $x = 0$, so $\\frac{y}{6} = 1$ and $y = 6$. Choice A is the x-intercept value placed on the y-axis. Choice C and choice D come from the slope magnitude $\\frac{6}{4}$ and its reciprocal, not from setting $x = 0$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='45a1a5a3-d2ae-dea1-a80b-98ace881e72b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2786cb48-6f3e-b6f1-6d2d-6013c43a7283','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The point $(a, 7)$ lies on the graph of $3x - 2y = 4$ in the xy-plane. What is the value of $a$?","options":[{"id":"A","label":"$-\\frac{10}{3}$"},{"id":"B","label":"$\\frac{11}{3}$"},{"id":"C","label":"$6$"},{"id":"D","label":"$18$"}]}'::jsonb,57,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2786cb48-6f3e-b6f1-6d2d-6013c43a7283','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Substitute $y = 7$: $3a - 14 = 4$, so $3a = 18$ and $a = 6$. Choice A treats $-2(7)$ as $+14$. Choice B substitutes 7 for $2y$ instead of for $y$. Choice D is the value of $3a$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2786cb48-6f3e-b6f1-6d2d-6013c43a7283') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5d0dd462-4545-cd6f-bb9b-87b3c8fefd31','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"Line $p$ in the xy-plane passes through $(-2, 3)$ and is parallel to the graph of $4x + 2y = 9$. If the equation of line $p$ is written in the form $y = mx + b$, what is the value of $b$?"}'::jsonb,58,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-014","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5d0dd462-4545-cd6f-bb9b-87b3c8fefd31','{"accepted":["-1"]}'::jsonb,'{"feedback":{"explanation":"Rewrite $4x + 2y = 9$ as $y = -2x + \\frac{9}{2}$, so a parallel line has slope $-2$. Using $(-2, 3)$: $3 = -2(-2) + b = 4 + b$, so $b = -1$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5d0dd462-4545-cd6f-bb9b-87b3c8fefd31') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ebca5064-9b87-a6b1-6d17-cd7c7074d92a','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A bakery uses 0.75 cup of sugar for each loaf of bread and 1.5 cups of sugar for each batch of cookies. On Monday the bakery used exactly 30 cups of sugar to make 16 loaves of bread and $k$ batches of cookies. What is the value of $k$?","options":[{"id":"A","label":"$8$"},{"id":"B","label":"$\\frac{28}{3}$"},{"id":"C","label":"$12$"},{"id":"D","label":"$24$"}]}'::jsonb,59,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ebca5064-9b87-a6b1-6d17-cd7c7074d92a','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The sugar equation is $0.75(16) + 1.5k = 30$. Since $0.75(16) = 12$, we get $1.5k = 18$, so $k = 12$. Choice A swaps the two amounts per item ($1.5(16) + 0.75k = 30$). Choice D correctly finds the 18 cups left for cookies but divides by 0.75, the amount for a loaf, instead of 1.5. Choice B subtracts the number of loaves, 16, from 30 instead of the sugar they use."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ebca5064-9b87-a6b1-6d17-cd7c7074d92a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('553bcf28-24fd-e62b-663a-93605dbfe068','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"In the xy-plane, the graph of $6x + ky = 18$, where $k$ is a constant, passes through the point $(2, -3)$. What is the value of $k$?","options":[{"id":"A","label":"$-10$"},{"id":"B","label":"$-2$"},{"id":"C","label":"$2$"},{"id":"D","label":"$10$"}]}'::jsonb,60,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '553bcf28-24fd-e62b-663a-93605dbfe068','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Substitute: $6(2) + k(-3) = 18$, so $12 - 3k = 18$, $-3k = 6$, and $k = -2$. Choice C drops the negative sign of $y = -3$. Choice A and choice D come from adding 12 to 18 instead of subtracting ($\\pm 3k = 30$)."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='553bcf28-24fd-e62b-663a-93605dbfe068') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('64f05c70-dc35-18bc-b607-d7c453a0642e','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"In the xy-plane, the graphs of $3x - ay = 7$ and $6x + 4y = 11$, where $a$ is a constant, are parallel. What is the value of $a$?"}'::jsonb,61,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-017","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '64f05c70-dc35-18bc-b607-d7c453a0642e','{"accepted":["-2"]}'::jsonb,'{"feedback":{"explanation":"Solve each for $y$. The first gives $y = \\frac{3}{a}x - \\frac{7}{a}$, slope $\\frac{3}{a}$. The second gives $y = -\\frac{3}{2}x + \\frac{11}{4}$, slope $-\\frac{3}{2}$. Parallel lines have equal slopes: $\\frac{3}{a} = -\\frac{3}{2}$, so $a = -2$. (The intercepts $\\frac{7}{2}$ and $\\frac{11}{4}$ differ, so the lines are distinct.)"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='64f05c70-dc35-18bc-b607-d7c453a0642e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('186fb0dc-759e-e849-3236-e4e1c8e47f55','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"A line in the xy-plane has slope $-\\frac{3}{5}$ and passes through the point $(10, -2)$. What is the sum of the x-coordinate of its x-intercept and the y-coordinate of its y-intercept?"}'::jsonb,62,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-018","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '186fb0dc-759e-e849-3236-e4e1c8e47f55','{"accepted":["32/3","10.66","10.67"]}'::jsonb,'{"feedback":{"explanation":"Point-slope form gives $y + 2 = -\\frac{3}{5}(x - 10)$, so $y = -\\frac{3}{5}x + 4$. The y-intercept is 4. Setting $y = 0$: $\\frac{3}{5}x = 4$, so $x = \\frac{20}{3}$. The sum is $4 + \\frac{20}{3} = \\frac{32}{3}$, which may be entered as 32/3 or 10.66 or 10.67."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='186fb0dc-759e-e849-3236-e4e1c8e47f55') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e6182980-5a9c-7e46-3569-ea75bd49de37','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"On a ferry, each car takes up 5 meters of lane space and each truck takes up 15 meters. When the ferry is loaded so that exactly 450 meters of lane space is used, the numbers of cars $c$ and trucks $t$ satisfy $5c + 15t = 450$. If the ferry is loaded to exactly 450 meters again but with 4 fewer trucks, how many more cars can it carry?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$4$"},{"id":"C","label":"$12$"},{"id":"D","label":"$60$"}]}'::jsonb,63,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e6182980-5a9c-7e46-3569-ea75bd49de37','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Removing 4 trucks frees $4 \\times 15 = 60$ meters, and each car needs 5 meters, so $\\frac{60}{5} = 12$ more cars fit. Equivalently, the slope of $c = 90 - 3t$ is $-3$, so a change of $-4$ in $t$ changes $c$ by $+12$. Choice A is the number of cars that replace one truck. Choice B assumes one car per truck. Choice D is the meters freed, not the number of cars."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e6182980-5a9c-7e46-3569-ea75bd49de37') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('937e85ea-4135-3a42-5fdf-a61fb4bf0538','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"Line $\\ell$ in the xy-plane passes through $(6, 7)$ and is perpendicular to the line through $(2, 1)$ and $(6, 7)$. What is the x-coordinate of the x-intercept of line $\\ell$?"}'::jsonb,64,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-020","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '937e85ea-4135-3a42-5fdf-a61fb4bf0538','{"accepted":["33/2","16.5"]}'::jsonb,'{"feedback":{"explanation":"The line through $(2, 1)$ and $(6, 7)$ has slope $\\frac{6}{4} = \\frac{3}{2}$, so $\\ell$ has slope $-\\frac{2}{3}$. Its equation is $y - 7 = -\\frac{2}{3}(x - 6)$. Setting $y = 0$: $-7 = -\\frac{2}{3}(x - 6)$, so $x - 6 = \\frac{21}{2}$ and $x = \\frac{33}{2}$, or 16.5."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='937e85ea-4135-3a42-5fdf-a61fb4bf0538') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('57410f70-ef1e-5ad3-17f3-1805d8e81ee7','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"In the xy-plane, the graph of $ax + by = 12$, where $a$ and $b$ are constants, has an x-intercept at $(2, 0)$ and a y-intercept at $(0, -3)$. What is the value of $a + b$?","options":[{"id":"A","label":"$-1$"},{"id":"B","label":"$2$"},{"id":"C","label":"$6$"},{"id":"D","label":"$10$"}]}'::jsonb,65,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '57410f70-ef1e-5ad3-17f3-1805d8e81ee7','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"At $(2, 0)$: $2a = 12$, so $a = 6$. At $(0, -3)$: $-3b = 12$, so $b = -4$. Then $a + b = 2$. Choice D uses $b = 4$, a sign error. Choice A adds the intercept coordinates $2 + (-3)$ instead of finding the coefficients. Choice C is the value of $a$ alone."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='57410f70-ef1e-5ad3-17f3-1805d8e81ee7') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('abca5050-e1f5-e379-a6d2-a2664ba76daa','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"In the xy-plane, the graph of $2y - kx = 8$, where $k$ is a constant, is perpendicular to the graph of $3x + 6y = 5$. What is the value of $k$?"}'::jsonb,66,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_equations_two_variables","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-lin2v-022","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'abca5050-e1f5-e379-a6d2-a2664ba76daa','{"accepted":["4"]}'::jsonb,'{"feedback":{"explanation":"The first line is $y = \\frac{k}{2}x + 4$, with slope $\\frac{k}{2}$. The second is $y = -\\frac{1}{2}x + \\frac{5}{6}$, with slope $-\\frac{1}{2}$. Perpendicular slopes multiply to $-1$: $\\frac{k}{2} \\cdot \\left(-\\frac{1}{2}\\right) = -1$, so $k = 4$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='abca5050-e1f5-e379-a6d2-a2664ba76daa') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('49c3e4ed-dfd5-a481-19f1-174745bba839','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$x + y = 10$$ $$x - y = 4$$ What is the value of $x$ in the solution $(x, y)$ to the system of equations?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$6$"},{"id":"C","label":"$7$"},{"id":"D","label":"$14$"}]}'::jsonb,67,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '49c3e4ed-dfd5-a481-19f1-174745bba839','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Add the equations: $2x = 14$, so $x = 7$ (and $y = 3$). Choice A is the value of $y$. Choice D is $2x$; remember to divide by 2. Choice B subtracts the constants, $10 - 4$, which equals $2y$, not $x$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='49c3e4ed-dfd5-a481-19f1-174745bba839') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('21b475dc-3663-9575-51f4-948e9ed0c497','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"$$y = 2x + 1$$ $$y = -x + 10$$ The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}'::jsonb,68,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '21b475dc-3663-9575-51f4-948e9ed0c497','{"accepted":["7"]}'::jsonb,'{"feedback":{"explanation":"Set the expressions for $y$ equal: $2x + 1 = -x + 10$, so $3x = 9$ and $x = 3$. Then $y = 2(3) + 1 = 7$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='21b475dc-3663-9575-51f4-948e9ed0c497') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2ecb8697-762b-a672-b747-9ef83d9ad21f','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A school play sold 50 tickets for a total of 520 dollars. Adult tickets cost 12 dollars each and student tickets cost 8 dollars each. Which system of equations can be used to find the number of adult tickets, $a$, and student tickets, $s$, that were sold?","options":[{"id":"A","label":"$a + s = 520$ and $12a + 8s = 50$"},{"id":"B","label":"$a + s = 50$ and $8a + 12s = 520$"},{"id":"C","label":"$12a + 8s = 50$ and $a + s = 20$"},{"id":"D","label":"$a + s = 50$ and $12a + 8s = 520$"}]}'::jsonb,69,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2ecb8697-762b-a672-b747-9ef83d9ad21f','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The number of tickets gives $a + s = 50$, and the revenue gives $12a + 8s = 520$. (The solution is $a = 30$, $s = 20$.) Choice A swaps the total count and the total revenue. Choice B attaches the adult price to student tickets. Choice C uses the revenue equation with the count total and an unsupported second equation."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2ecb8697-762b-a672-b747-9ef83d9ad21f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b58f54e8-742c-b546-95bf-fea4bc15fbe9','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$2x + y = 11$$ $$x - y = 1$$ If $(x, y)$ is the solution to the system of equations, what is the value of $x$?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$4$"},{"id":"C","label":"$\\frac{11}{2}$"},{"id":"D","label":"$10$"}]}'::jsonb,70,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b58f54e8-742c-b546-95bf-fea4bc15fbe9','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Adding the equations eliminates $y$: $3x = 12$, so $x = 4$ and then $y = 3$. Choice A is $y$. Choice C solves $2x = 11$, ignoring $y$. Choice D subtracts the constants instead of adding the equations."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b58f54e8-742c-b546-95bf-fea4bc15fbe9') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('91a96e37-6dc1-c203-50ab-deaa0220d23b','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$4x + 3y = 25$$ $$4x - 3y = 7$$ What is the value of $x$ in the solution to the system?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$4$"},{"id":"C","label":"$8$"},{"id":"D","label":"$32$"}]}'::jsonb,71,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '91a96e37-6dc1-c203-50ab-deaa0220d23b','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Add the equations: $8x = 32$, so $x = 4$. (Subtracting gives $6y = 18$, so $y = 3$.) Choice A is $y$. Choice C is $2x$, and choice D is $8x$; both stop before dividing."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='91a96e37-6dc1-c203-50ab-deaa0220d23b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bed3d04f-80c4-4f4c-9d47-6b8be994c25c','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"The graphs of the equations $y = 2x - 1$ and $y = -\\frac{1}{2}x + 4$ are shown in the xy-plane. What is the solution $(x, y)$ to the system of these two equations?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 300 375\" width=\"300\" height=\"375\" role=\"img\" aria-label=\"Two lines that intersect at the point (2, 3)\" font-family=\"sans-serif\" font-size=\"10\"><title>Two lines that intersect at the point (2, 3)</title><path d=\"M24.0 351.0V24.0M55.5 351.0V24.0M87.0 351.0V24.0M118.5 351.0V24.0M150.0 351.0V24.0M181.5 351.0V24.0M213.0 351.0V24.0M244.5 351.0V24.0M276.0 351.0V24.0M24.0 351.0H276.0M24.0 318.3H276.0M24.0 285.6H276.0M24.0 252.9H276.0M24.0 220.2H276.0M24.0 187.5H276.0M24.0 154.8H276.0M24.0 122.1H276.0M24.0 89.4H276.0M24.0 56.7H276.0M24.0 24.0H276.0\" stroke=\"currentColor\" stroke-opacity=\"0.18\" stroke-width=\"1\" fill=\"none\"/><path d=\"M24.0 252.9H276.0M87.0 351.0V24.0\" stroke=\"currentColor\" stroke-width=\"1.4\" fill=\"none\"/><text x=\"280.0\" y=\"256.9\" fill=\"currentColor\" font-style=\"italic\" font-size=\"12\">x</text><text x=\"83.0\" y=\"16.0\" fill=\"currentColor\" font-style=\"italic\" font-size=\"12\">y</text><text x=\"24.0\" y=\"264.9\" text-anchor=\"middle\" fill=\"currentColor\">-2</text><text x=\"55.5\" y=\"264.9\" text-anchor=\"middle\" fill=\"currentColor\">-1</text><text x=\"118.5\" y=\"264.9\" text-anchor=\"middle\" fill=\"currentColor\">1</text><text x=\"150.0\" y=\"264.9\" text-anchor=\"middle\" fill=\"currentColor\">2</text><text x=\"181.5\" y=\"264.9\" text-anchor=\"middle\" fill=\"currentColor\">3</text><text x=\"213.0\" y=\"264.9\" text-anchor=\"middle\" fill=\"currentColor\">4</text><text x=\"244.5\" y=\"264.9\" text-anchor=\"middle\" fill=\"currentColor\">5</text><text x=\"276.0\" y=\"264.9\" text-an