L143.7 151.5L144.8 152.1L145.8 152.6L146.8 153.2L147.9 153.7L148.9 154.3L150.0 154.8L151.1 155.3L152.1 155.9L153.1 156.4L154.2 157.0L155.2 157.5L156.3 158.1L157.3 158.6L158.4 159.2L159.4 159.7L160.5 160.2L161.5 160.8L162.6 161.3L163.7 161.9L164.7 162.4L165.8 163.0L166.8 163.5L167.8 164.1L168.9 164.6L170.0 165.2L171.0 165.7L172.1 166.2L173.1 166.8L174.2 167.3L175.2 167.9L176.2 168.4L177.3 169.0L178.4 169.5L179.4 170.1L180.5 170.6L181.5 171.1L182.5 171.7L183.6 172.2L184.6 172.8L185.7 173.3L186.8 173.9L187.8 174.4L188.8 175.0L189.9 175.5L190.9 176.1L192.0 176.6L193.0 177.1L194.1 177.7L195.2 178.2L196.2 178.8L197.2 179.3L198.3 179.9L199.3 180.4L200.4 181.0L201.5 181.5L202.5 182.1L203.6 182.6L204.6 183.1L205.7 183.7L206.7 184.2L207.8 184.8L208.8 185.3L209.9 185.9L210.9 186.4L212.0 187.0L213.0 187.5L214.0 188.0L215.1 188.6L216.1 189.1L217.2 189.7L218.2 190.2L219.3 190.8L220.3 191.3L221.4 191.9L222.4 192.4L223.5 192.9L224.5 193.5L225.6 194.0L226.7 194.6L227.7 195.1L228.8 195.7L229.8 196.2L230.8 196.8L231.9 197.3L233.0 197.9L234.0 198.4L235.1 198.9L236.1 199.5L237.2 200.0L238.2 200.6L239.2 201.1L240.3 201.7L241.4 202.2L242.4 202.8L243.5 203.3L244.5 203.8L245.5 204.4L246.6 204.9L247.6 205.5L248.7 206.0L249.8 206.6L250.8 207.1L251.8 207.7L252.9 208.2L253.9 208.8L255.0 209.3L256.0 209.8L257.1 210.4L258.1 210.9L259.2 211.5L260.2 212.0L261.3 212.6L262.4 213.1L263.4 213.7L264.5 214.2L265.5 214.8L266.6 215.3L267.6 215.8L268.6 216.4L269.7 216.9L270.8 217.5L271.8 218.0L272.9 218.6L273.9 219.1L275.0 219.7L276.0 220.2\" stroke=\"#dc2626\" stroke-width=\"2\" fill=\"none\"/><circle cx=\"150.0\" cy=\"154.8\" r=\"3\" fill=\"currentColor\"/><text x=\"222.4\" y=\"46.9\" fill=\"#2563eb\" font-size=\"11\" font-style=\"italic\">y = 2x − 1</text><text x=\"200.4\" y=\"220.2\" fill=\"#dc2626\" font-size=\"11\" font-style=\"italic\">y = −x/2 + 4</text></svg>","options":[{"id":"A","label":"$(2, 3)$"},{"id":"B","label":"$(0, 4)$"},{"id":"C","label":"$(3, 2)$"},{"id":"D","label":"$(\\frac{1}{2}, 0)$"}]}'::jsonb,72,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'bed3d04f-80c4-4f4c-9d47-6b8be994c25c','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The solution is the intersection point, $(2, 3)$. Check: $2(2) - 1 = 3$ and $-\\frac{1}{2}(2) + 4 = 3$. Choice C swaps the coordinates. Choice B is the y-intercept of only the second line, and choice D is the x-intercept of only the first line."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='bed3d04f-80c4-4f4c-9d47-6b8be994c25c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9a9c30e7-46f4-2102-659e-585879427519','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A farm has only chickens and goats. Altogether the animals have 30 heads and 84 legs. Each chicken has 2 legs and each goat has 4 legs. How many goats are on the farm?","options":[{"id":"A","label":"$12$"},{"id":"B","label":"$18$"},{"id":"C","label":"$21$"},{"id":"D","label":"$24$"}]}'::jsonb,73,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9a9c30e7-46f4-2102-659e-585879427519','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Let $c$ and $g$ be the numbers of chickens and goats: $c + g = 30$ and $2c + 4g = 84$. Doubling the first equation gives $2c + 2g = 60$; subtracting from the second gives $2g = 24$, so $g = 12$ (and $c = 18$). Choice B is the number of chickens. Choice C assumes every leg belongs to a goat ($84 \\div 4$). Choice D is $2g$; it still needs to be divided by 2."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9a9c30e7-46f4-2102-659e-585879427519') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f6f464c0-8407-07a4-722c-481ffb49bea2','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$kx + 3y = 9$$ $$4x + 6y = 5$$ In the system of equations, $k$ is a constant. For what value of $k$ does the system have no solution?","options":[{"id":"A","label":"$\\frac{1}{2}$"},{"id":"B","label":"$2$"},{"id":"C","label":"$4$"},{"id":"D","label":"$8$"}]}'::jsonb,74,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f6f464c0-8407-07a4-722c-481ffb49bea2','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"A system of two linear equations has no solution when the lines are parallel and distinct. Multiplying the first equation by 2 gives $2kx + 6y = 18$; this is parallel to $4x + 6y = 5$ when $2k = 4$, so $k = 2$, and the constants 18 and 5 differ. Choice C copies the coefficient 4 without matching the $y$-coefficients. Choice D doubles the 4 instead of halving it, and choice A inverts the ratio $\\frac{4}{2}$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f6f464c0-8407-07a4-722c-481ffb49bea2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9bf6f01a-d4be-3ef3-304b-dd502848ea56','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"$$2x - 5y = 8$$ $$6x + ay = 24$$ In the system of equations, $a$ is a constant. If the system has infinitely many solutions, what is the value of $a$?"}'::jsonb,75,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-009","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9bf6f01a-d4be-3ef3-304b-dd502848ea56','{"accepted":["-15"]}'::jsonb,'{"feedback":{"explanation":"For infinitely many solutions, the second equation must be a multiple of the first. Since $6 = 3 \\times 2$ and $24 = 3 \\times 8$, the multiplier is 3, so $a = 3 \\times (-5) = -15$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9bf6f01a-d4be-3ef3-304b-dd502848ea56') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('74734aff-ff96-9b22-1792-64b28950c6fe','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"A cafe sold 140 coffees on Friday, each either small or large. Small coffees cost 3 dollars and large coffees cost 4.50 dollars, and the cafe''s coffee sales totaled 513 dollars. How many large coffees did the cafe sell?"}'::jsonb,76,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-010","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '74734aff-ff96-9b22-1792-64b28950c6fe','{"accepted":["62"]}'::jsonb,'{"feedback":{"explanation":"Let $s$ and $\\ell$ be the numbers of small and large coffees: $s + \\ell = 140$ and $3s + 4.5\\ell = 513$. Multiplying the first equation by 3 gives $3s + 3\\ell = 420$. Subtracting, $1.5\\ell = 93$, so $\\ell = 62$ (and $s = 78$)."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='74734aff-ff96-9b22-1792-64b28950c6fe') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('aed0daff-e50b-8ee5-1717-7b2c4b7c7690','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$y = 3x - 4$$ $$6x - 2y = 8$$ How many solutions does the system of equations have?","options":[{"id":"A","label":"Zero"},{"id":"B","label":"Exactly one"},{"id":"C","label":"Exactly two"},{"id":"D","label":"Infinitely many"}]}'::jsonb,77,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'aed0daff-e50b-8ee5-1717-7b2c4b7c7690','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Substitute $y = 3x - 4$ into the second equation: $6x - 2(3x - 4) = 6x - 6x + 8 = 8$, which is always true. The equations describe the same line, so there are infinitely many solutions. Choice A would require parallel, distinct lines, and choice B would require different slopes; here both lines have slope 3 and y-intercept $-4$. Two distinct lines can never meet in exactly two points (choice C)."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='aed0daff-e50b-8ee5-1717-7b2c4b7c7690') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('14835018-fd0e-92cb-e549-84adb82c0f52','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$3x - 2y = 1$$ $$5x + 2y = 23$$ If $(a, b)$ is the solution to the system of equations, what is the value of $\\frac{a}{b}$?","options":[{"id":"A","label":"$\\frac{3}{4}$"},{"id":"B","label":"$\\frac{4}{3}$"},{"id":"C","label":"$7$"},{"id":"D","label":"$12$"}]}'::jsonb,78,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '14835018-fd0e-92cb-e549-84adb82c0f52','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Adding the equations gives $8x = 24$, so $a = 3$. Then $3(3) - 2y = 1$ gives $b = 4$. So $\\frac{a}{b} = \\frac{3}{4}$. Choice B is $\\frac{b}{a}$. Choice D is $ab$, and choice C is $a + b$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='14835018-fd0e-92cb-e549-84adb82c0f52') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('cb6dc476-9b7d-ec9e-d2e8-44e990fdefb2','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A boat travels 36 kilometers downstream in 2 hours and returns the same 36 kilometers upstream in 3 hours. Assuming the boat''s speed in still water and the speed of the current are constant, what is the speed of the boat in still water, in kilometers per hour?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$12$"},{"id":"C","label":"$15$"},{"id":"D","label":"$18$"}]}'::jsonb,79,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'cb6dc476-9b7d-ec9e-d2e8-44e990fdefb2','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Downstream the speeds add: $b + c = \\frac{36}{2} = 18$. Upstream they subtract: $b - c = \\frac{36}{3} = 12$. Adding gives $2b = 30$, so $b = 15$ (and $c = 3$). Choice A is the current''s speed. Choice D and choice B are the downstream and upstream speeds, not the boat''s speed in still water."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='cb6dc476-9b7d-ec9e-d2e8-44e990fdefb2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2c97c939-66ee-5b93-a33f-938e3ed22706','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$x = 2y + 1$$ $$3x - 5y = 8$$ What is the value of $x$ in the solution $(x, y)$ to the system of equations?","options":[{"id":"A","label":"$5$"},{"id":"B","label":"$9$"},{"id":"C","label":"$11$"},{"id":"D","label":"$15$"}]}'::jsonb,80,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2c97c939-66ee-5b93-a33f-938e3ed22706','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Substitute: $3(2y + 1) - 5y = 8$, so $6y + 3 - 5y = 8$ and $y = 5$. Then $x = 2(5) + 1 = 11$. Choice A is the value of $y$. Choice B finds $y = 5$ but then computes $x = 2y - 1$. Choice D comes from writing $3(2y + 1)$ as $6y + 1$, which gives $y = 7$ and $x = 15$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2c97c939-66ee-5b93-a33f-938e3ed22706') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('be2d9ed2-ec8e-f509-ac8f-9bf62afe6539','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Which of the following systems of equations has exactly one solution?","options":[{"id":"A","label":"$2x + 3y = 6$ and $4x + 6y = 12$"},{"id":"B","label":"$2x + 3y = 6$ and $3x + 2y = 6$"},{"id":"C","label":"$2x + 3y = 6$ and $4x + 6y = 7$"},{"id":"D","label":"$y = 5x + 1$ and $y = 5x - 1$"}]}'::jsonb,81,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'be2d9ed2-ec8e-f509-ac8f-9bf62afe6539','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"A system has exactly one solution when the lines have different slopes. In choice B the slopes are $-\\frac{2}{3}$ and $-\\frac{3}{2}$, which differ (the lines meet at $(\\frac{6}{5}, \\frac{6}{5})$). In choice A the second equation is twice the first: infinitely many solutions. In choice C and choice D the lines are parallel and distinct: no solution."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='be2d9ed2-ec8e-f509-ac8f-9bf62afe6539') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ab410c13-49f1-0efd-ff19-a82700317deb','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"$$3x + ky = 12$$ $$kx + 12y = 24$$ In the system of equations, $k$ is a constant. If the system has no solution, what is the value of $k$?"}'::jsonb,82,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-016","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ab410c13-49f1-0efd-ff19-a82700317deb','{"accepted":["-6"]}'::jsonb,'{"feedback":{"explanation":"No solution requires parallel lines: the coefficients must be proportional, $\\frac{3}{k} = \\frac{k}{12}$, so $k^2 = 36$ and $k = 6$ or $k = -6$. If $k = 6$, the equations are $3x + 6y = 12$ and $6x + 12y = 24$, which are the same line (infinitely many solutions). If $k = -6$, they are $3x - 6y = 12$, or $x - 2y = 4$, and $-6x + 12y = 24$, or $x - 2y = -4$: parallel and distinct. So $k = -6$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ab410c13-49f1-0efd-ff19-a82700317deb') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6da6e2bb-a085-cd38-aa0f-4c4db723e4cf','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A chemist mixes a solution that is 15% acid with a solution that is 40% acid to make 50 liters of a mixture that is 25% acid. How many liters of the 40% solution does the chemist use?","options":[{"id":"A","label":"$20$"},{"id":"B","label":"$25$"},{"id":"C","label":"$\\frac{125}{4}$"},{"id":"D","label":"$30$"}]}'::jsonb,83,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '6da6e2bb-a085-cd38-aa0f-4c4db723e4cf','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Let $a$ and $b$ be the liters of 15% and 40% solution: $a + b = 50$ and $0.15a + 0.40b = 0.25(50) = 12.5$. Substituting $a = 50 - b$: $7.5 + 0.25b = 12.5$, so $b = 20$. Choice D is the amount of 15% solution. Choice B assumes equal amounts, which would give a 27.5% mixture. Choice C scales 50 liters by $\\frac{25}{40}$, ignoring the acid in the 15% solution."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='6da6e2bb-a085-cd38-aa0f-4c4db723e4cf') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('60e4b9b2-954f-e255-090d-9e081434de73','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"$$y = ax + 4$$ $$y = 3x + b$$ In the system of equations, $a$ and $b$ are constants. The graphs of the equations intersect at the point $(2, 12)$. What is the value of $a + b$?"}'::jsonb,84,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-018","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '60e4b9b2-954f-e255-090d-9e081434de73','{"accepted":["10"]}'::jsonb,'{"feedback":{"explanation":"Substitute $(2, 12)$ into each equation. First: $12 = 2a + 4$, so $a = 4$. Second: $12 = 6 + b$, so $b = 6$. Thus $a + b = 10$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='60e4b9b2-954f-e255-090d-9e081434de73') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('da6954d0-9046-cda0-197c-8b948c4ad6d0','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$4x - 3y = 5$$ $$12x + ry = s$$ In the system of equations, $r$ and $s$ are constants. If the system has infinitely many solutions, what is the value of $r + s$?","options":[{"id":"A","label":"$-4$"},{"id":"B","label":"$2$"},{"id":"C","label":"$6$"},{"id":"D","label":"$24$"}]}'::jsonb,85,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'da6954d0-9046-cda0-197c-8b948c4ad6d0','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The second equation must be 3 times the first: $12x - 9y = 15$. So $r = -9$, $s = 15$, and $r + s = 6$. Choice D uses $r = 9$, losing the negative sign. Choice B adds the original coefficients $-3$ and 5 without scaling. Choice A scales only the $y$-coefficient."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='da6954d0-9046-cda0-197c-8b948c4ad6d0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2bf73468-1804-3abe-360b-34e15a3ca640','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"At a fair, 3 ride wristbands and 2 meal vouchers cost 46 dollars, and 2 ride wristbands and 5 meal vouchers cost 49 dollars. What is the total cost, in dollars, of 1 ride wristband and 1 meal voucher?"}'::jsonb,86,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-020","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2bf73468-1804-3abe-360b-34e15a3ca640','{"accepted":["17"]}'::jsonb,'{"feedback":{"explanation":"Let $w$ and $m$ be the prices: $3w + 2m = 46$ and $2w + 5m = 49$. Multiply the first by 2 and the second by 3: $6w + 4m = 92$ and $6w + 15m = 147$. Subtracting gives $11m = 55$, so $m = 5$, and then $3w = 36$ gives $w = 12$. The total is $12 + 5 = 17$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2bf73468-1804-3abe-360b-34e15a3ca640') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f6f59fe6-709d-048f-137d-ac70d13bc566','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$3x + 5y = 41$$ $$5x + 3y = 39$$ If $(x, y)$ satisfies the system of equations, what is the value of $x + y$?","options":[{"id":"A","label":"$\\frac{9}{2}$"},{"id":"B","label":"$10$"},{"id":"C","label":"$\\frac{11}{2}$"},{"id":"D","label":"$40$"}]}'::jsonb,87,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f6f59fe6-709d-048f-137d-ac70d13bc566','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Adding the equations gives $8x + 8y = 80$, so $x + y = 10$ directly. (Solving fully gives $x = \\frac{9}{2}$ and $y = \\frac{11}{2}$.) Choice A and choice C are the individual values of $x$ and $y$. Choice D adds the equations but divides $41 + 39$ by 2 instead of by 8."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f6f59fe6-709d-048f-137d-ac70d13bc566') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9db255e1-65d7-cd3f-e136-474db08969df','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$2x + 3y = 7$$ $$cx - 9y = 4$$ In the system of equations, $c$ is a constant. The system has exactly one solution for every value of $c$ except one. What is that value of $c$?","options":[{"id":"A","label":"$-9$"},{"id":"B","label":"$-6$"},{"id":"C","label":"$-\\frac{3}{2}$"},{"id":"D","label":"$6$"}]}'::jsonb,88,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"systems_of_linear_equations","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-sys-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9db255e1-65d7-cd3f-e136-474db08969df','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The system fails to have exactly one solution only when the lines are parallel, that is, when the coefficients are proportional: $\\frac{c}{2} = \\frac{-9}{3}$, so $c = -6$. (Then $-6x - 9y = 4$ is parallel to $-6x - 9y = -21$, so there is no solution.) Choice D loses the negative sign. Choice A copies the $y$-coefficient. Choice C inverts the ratio."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9db255e1-65d7-cd3f-e136-474db08969df') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('81e06827-47e3-b161-433e-ac8320124782','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Which inequality describes all solutions to $3x - 5 > 10$?","options":[{"id":"A","label":"$x > \\frac{5}{3}$"},{"id":"B","label":"$x > 5$"},{"id":"C","label":"$x < 5$"},{"id":"D","label":"$x > 15$"}]}'::jsonb,89,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '81e06827-47e3-b161-433e-ac8320124782','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Add 5 to both sides: $3x > 15$. Divide by the positive number 3, which keeps the direction: $x > 5$. Choice C reverses the inequality without a reason (only dividing by a negative number does that). Choice D stops before dividing. Choice A subtracts 5 instead of adding it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='81e06827-47e3-b161-433e-ac8320124782') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d19c0785-5788-80c1-f045-91c0a82accf2','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Which value of $x$ satisfies the inequality $2x + 7 \\le 1$?","options":[{"id":"A","label":"$-4$"},{"id":"B","label":"$-2$"},{"id":"C","label":"$0$"},{"id":"D","label":"$3$"}]}'::jsonb,90,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'd19c0785-5788-80c1-f045-91c0a82accf2','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Subtract 7: $2x \\le -6$, so $x \\le -3$. Only $-4$ is at most $-3$. Choice B, $-2$, gives $2(-2) + 7 = 3$, which is greater than 1. Choice C and choice D give 7 and 13."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='d19c0785-5788-80c1-f045-91c0a82accf2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3c79ec69-559d-9acf-2bd4-e0fe9ad575de','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A freight elevator can safely carry at most 500 kilograms. Its operator weighs 80 kilograms, and each box to be moved weighs 18 kilograms. What is the greatest number of boxes the operator can take in the elevator in one trip?","options":[{"id":"A","label":"$23$"},{"id":"B","label":"$24$"},{"id":"C","label":"$27$"},{"id":"D","label":"$32$"}]}'::jsonb,91,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3c79ec69-559d-9acf-2bd4-e0fe9ad575de','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The load must satisfy $80 + 18b \\le 500$, so $18b \\le 420$ and $b \\le 23.\\overline{3}$. The number of boxes must be a whole number, so the greatest possible value is 23. Choice B rounds up; 24 boxes would make the load $80 + 432 = 512$ kilograms. Choice C ignores the operator''s weight. Choice D adds the operator''s weight to the limit instead of subtracting it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3c79ec69-559d-9acf-2bd4-e0fe9ad575de') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b602f81e-8ebd-aaf8-dc02-8d87f35976b1','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Which inequality is equivalent to $-4x \\ge 12$?","options":[{"id":"A","label":"$x \\ge -3$"},{"id":"B","label":"$x \\ge 3$"},{"id":"C","label":"$x \\le -3$"},{"id":"D","label":"$x \\le 3$"}]}'::jsonb,92,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b602f81e-8ebd-aaf8-dc02-8d87f35976b1','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Divide both sides by $-4$ and reverse the inequality, since dividing by a negative number reverses order: $x \\le -3$. Choice A forgets to reverse the sign. Choice B and choice D drop the negative sign from the quotient."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b602f81e-8ebd-aaf8-dc02-8d87f35976b1') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e557e170-0e6d-b6e9-c2d8-0a49f959061f','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"Maria has 62 points in a reading challenge and earns 4 points for each book report she completes. What is the minimum number of book reports she must complete to have at least 85 points?"}'::jsonb,93,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-005","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e557e170-0e6d-b6e9-c2d8-0a49f959061f','{"accepted":["6"]}'::jsonb,'{"feedback":{"explanation":"She needs $62 + 4r \\ge 85$, so $4r \\ge 23$ and $r \\ge 5.75$. Since $r$ is a whole number, the minimum is 6. Five reports would give only $62 + 20 = 82$ points."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e557e170-0e6d-b6e9-c2d8-0a49f959061f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c6f2aa0a-6d0a-838e-7308-ec7549d7c622','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A number $n$ increased by 9 is at most 30. Which inequality represents this statement?","options":[{"id":"A","label":"$n + 9 < 30$"},{"id":"B","label":"$9n \\le 30$"},{"id":"C","label":"$n + 9 \\ge 30$"},{"id":"D","label":"$n + 9 \\le 30$"}]}'::jsonb,94,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c6f2aa0a-6d0a-838e-7308-ec7549d7c622','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"\\\"Increased by 9\\\" means $n + 9$, and \\\"at most 30\\\" means less than or equal to 30, so $n + 9 \\le 30$. Choice A excludes $n + 9 = 30$, which \\\"at most\\\" allows. Choice C means \\\"at least.\\\" Choice B multiplies by 9 instead of adding."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c6f2aa0a-6d0a-838e-7308-ec7549d7c622') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('843b7cb1-3af9-3ba7-8e06-c852a3803647','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Which point $(x, y)$ is a solution to the inequality $y > 2x - 3$?","options":[{"id":"A","label":"$(1, 0)$"},{"id":"B","label":"$(2, 1)$"},{"id":"C","label":"$(3, 2)$"},{"id":"D","label":"$(4, 4)$"}]}'::jsonb,95,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '843b7cb1-3af9-3ba7-8e06-c852a3803647','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"For $(1, 0)$: $2(1) - 3 = -1$, and $0 > -1$ is true. For $(2, 1)$: $1 > 1$ is false because the inequality is strict. For $(3, 2)$: $2 > 3$ is false. For $(4, 4)$: $4 > 5$ is false. So choice B, choice C and choice D are not solutions."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='843b7cb1-3af9-3ba7-8e06-c852a3803647') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b042942d-d062-dc05-6297-ac6d19ea797e','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Which inequality describes all solutions to $5 - x < 2$?","options":[{"id":"A","label":"$x < 3$"},{"id":"B","label":"$x > 3$"},{"id":"C","label":"$x < -3$"},{"id":"D","label":"$x > 7$"}]}'::jsonb,96,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b042942d-d062-dc05-6297-ac6d19ea797e','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Subtract 5: $-x < -3$. Multiply by $-1$ and reverse the inequality: $x > 3$. Choice A forgets to reverse the inequality. Choice C drops a negative sign. Choice D adds 5 to 2 instead of subtracting."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b042942d-d062-dc05-6297-ac6d19ea797e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9b8acfc6-9e87-d6b4-71bc-c83e5db67cc2','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"How many integers $x$ satisfy $-3 < 2x + 1 \\le 9$?"}'::jsonb,97,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-009","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9b8acfc6-9e87-d6b4-71bc-c83e5db67cc2','{"accepted":["6"]}'::jsonb,'{"feedback":{"explanation":"Subtract 1 from all three parts: $-4 < 2x \\le 8$. Divide by 2: $-2 < x \\le 4$. The integers are $-1, 0, 1, 2, 3, 4$, so there are 6. Note that $-2$ is excluded because the left inequality is strict, while 4 is included."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9b8acfc6-9e87-d6b4-71bc-c83e5db67cc2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('35df56cd-bd8d-7a22-b438-5a7ce940699f','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Phone plan A costs 30 dollars per month plus 0.10 dollar per text message. Plan B costs 45 dollars per month with unlimited texts. Which inequality gives all numbers of texts $t$ in a month for which plan A costs less than plan B?","options":[{"id":"A","label":"$t < 450$"},{"id":"B","label":"$t > 150$"},{"id":"C","label":"$t < 150$"},{"id":"D","label":"$t < 15$"}]}'::jsonb,98,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '35df56cd-bd8d-7a22-b438-5a7ce940699f','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Plan A is cheaper when $30 + 0.10t < 45$, so $0.10t < 15$ and $t < 150$. Choice B reverses the comparison. Choice A divides 45 by 0.10 without first subtracting the 30-dollar base fee. Choice D stops at $0.10t < 15$ and forgets to divide by 0.10."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='35df56cd-bd8d-7a22-b438-5a7ce940699f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('165dedf7-4470-f616-7bb1-a752a5e3b872','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"$$y \\le 2x + 3$$ $$y > -x + 1$$ Which point $(x, y)$ is a solution to the system of inequalities?","options":[{"id":"A","label":"$(0, 0)$"},{"id":"B","label":"$(-1, 2)$"},{"id":"C","label":"$(2, 8)$"},{"id":"D","label":"$(1, 4)$"}]}'::jsonb,99,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '165dedf7-4470-f616-7bb1-a752a5e3b872','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"For $(1, 4)$: $4 \\le 2(1) + 3 = 5$ is true, and $4 > -1 + 1 = 0$ is true, so it satisfies both. For $(0, 0)$, the second inequality fails because $0 > 1$ is false. For $(-1, 2)$, the first fails: $2 \\le 1$ is false. For $(2, 8)$, the first fails: $8 \\le 7$ is false. Choice A, choice B and choice C each satisfy at most one inequality."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='165dedf7-4470-f616-7bb1-a752a5e3b872') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5c97e95f-1470-6e02-199f-4a305eee2ea4','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A volunteer packs between 40 and 55 food boxes per hour, inclusive. Which of the following could be the number of hours it takes the volunteer to pack 400 boxes?","options":[{"id":"A","label":"$6$"},{"id":"B","label":"$7$"},{"id":"C","label":"$9$"},{"id":"D","label":"$11$"}]}'::jsonb,100,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5c97e95f-1470-6e02-199f-4a305eee2ea4','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"At the fastest rate the job takes $\\frac{400}{55} \\approx 7.3$ hours, and at the slowest rate it takes $\\frac{400}{40} = 10$ hours. So the time $h$ satisfies $\\frac{80}{11} \\le h \\le 10$, and only 9 hours is possible. In 7 hours (choice B) even the fastest rate gives only $7 \\times 55 = 385$ boxes. Choice A is too short as well, and in 11 hours (choice D) even the slowest rate gives 440 boxes."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5c97e95f-1470-6e02-199f-4a305eee2ea4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dcad82ab-6388-a10e-9aad-054607da6b34','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"If $3a - 2 > 13$, which of the following must be true?","options":[{"id":"A","label":"$2a > 10$"},{"id":"B","label":"$a > 6$"},{"id":"C","label":"$a < 5$"},{"id":"D","label":"$a > \\frac{11}{3}$ and $a < 6$"}]}'::jsonb,101,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'dcad82ab-6388-a10e-9aad-054607da6b34','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Add 2 and divide by 3: $a > 5$. Multiplying by 2 gives $2a > 10$, which must be true. Choice B is not guaranteed: $a = 5.5$ satisfies the inequality but not $a > 6$. Choice C contradicts $a > 5$. Choice D fails for large values such as $a = 7$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='dcad82ab-6388-a10e-9aad-054607da6b34') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('97762731-ba3c-0226-336a-36846dcdf4bb','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"What is the greatest value of $x$ that satisfies $4(x - 2) \\ge 6x + 4$?"}'::jsonb,102,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-014","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '97762731-ba3c-0226-336a-36846dcdf4bb','{"accepted":["-6"]}'::jsonb,'{"feedback":{"explanation":"Distribute: $4x - 8 \\ge 6x + 4$. Subtract $6x$ and add 8: $-2x \\ge 12$. Divide by $-2$ and reverse the inequality: $x \\le -6$. The greatest value is $-6$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='97762731-ba3c-0226-336a-36846dcdf4bb') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('20501f74-aa72-b0d2-a91b-f371015a6507','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A delivery truck can carry at most 2,000 kilograms. It is loaded with $c$ crates that weigh 45 kilograms each and $b$ barrels that weigh 70 kilograms each. Which inequality represents this situation?","options":[{"id":"A","label":"$45c + 70b \\ge 2{,}000$"},{"id":"B","label":"$45c + 70b \\le 2{,}000$"},{"id":"C","label":"$70c + 45b \\le 2{,}000$"},{"id":"D","label":"$c + b \\le 2{,}000$"}]}'::jsonb,103,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '20501f74-aa72-b0d2-a91b-f371015a6507','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Crates contribute $45c$ kilograms and barrels contribute $70b$ kilograms, and \\\"at most\\\" means $\\le$. Choice A means at least 2,000 kilograms. Choice C swaps the weights. Choice D counts items instead of kilograms."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='20501f74-aa72-b0d2-a91b-f371015a6507') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('37bc757f-65aa-abb7-bb77-204762c0ad7e','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"Which point $(x, y)$ is NOT a solution to the inequality $2x - 3y > 6$?","options":[{"id":"A","label":"$(0, -3)$"},{"id":"B","label":"$(4, 0)$"},{"id":"C","label":"$(3, 0)$"},{"id":"D","label":"$(1, -2)$"}]}'::jsonb,104,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '37bc757f-65aa-abb7-bb77-204762c0ad7e','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"For $(3, 0)$: $2(3) - 0 = 6$, and $6 > 6$ is false, so this point is not a solution; it lies on the boundary line, which is excluded. Choice A, choice B and choice D are solutions: $(0, -3)$ gives 9, $(4, 0)$ gives 8, and $(1, -2)$ gives 8, and each of those exceeds 6."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='37bc757f-65aa-abb7-bb77-204762c0ad7e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('59b29a3f-6c06-d064-44d8-7d903d45553b','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A bakery sells muffins for 2.75 dollars each. Each muffin costs the bakery 0.95 dollar to make, and the bakery also pays a fixed cost of 180 dollars per day. What is the minimum number of muffins the bakery must sell in a day to earn a profit of at least 270 dollars that day?","options":[{"id":"A","label":"$150$"},{"id":"B","label":"$164$"},{"id":"C","label":"$250$"},{"id":"D","label":"$474$"}]}'::jsonb,105,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '59b29a3f-6c06-d064-44d8-7d903d45553b','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Profit is $2.75n - (0.95n + 180) = 1.8n - 180$. Solving $1.8n - 180 \\ge 270$ gives $1.8n \\ge 450$, so $n \\ge 250$. Choice A ignores the fixed cost ($1.8n \\ge 270$). Choice B ignores the cost per muffin ($2.75n \\ge 450$ gives $n \\ge 163.6$). Choice D divides 450 by the cost per muffin instead of by the profit per muffin."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='59b29a3f-6c06-d064-44d8-7d903d45553b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('911a9c5c-ab84-7942-bebc-4a46b534ab6a','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"In the inequality $3(x - k) > 2x + 5$, $k$ is a constant. The solution set of the inequality is $x > 11$. What is the value of $k$?"}'::jsonb,106,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-018","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '911a9c5c-ab84-7942-bebc-4a46b534ab6a','{"accepted":["2"]}'::jsonb,'{"feedback":{"explanation":"Distribute: $3x - 3k > 2x + 5$. Subtract $2x$ and add $3k$: $x > 3k + 5$. This must be the same as $x > 11$, so $3k + 5 = 11$ and $k = 2$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='911a9c5c-ab84-7942-bebc-4a46b534ab6a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dde5eb38-0a93-c316-14f0-cfe02f27fc03','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"Gym X charges a 40-dollar enrollment fee plus 25 dollars per month. Gym Y has no enrollment fee and charges 15 dollars per month plus 3 dollars per visit. Kofi will visit the gym 8 times each month. What is the minimum number of whole months of membership for which Gym X would cost Kofi less in total than Gym Y?"}'::jsonb,107,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-019","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'dde5eb38-0a93-c316-14f0-cfe02f27fc03','{"accepted":["3"]}'::jsonb,'{"feedback":{"explanation":"After $m$ months, Gym X costs $40 + 25m$ and Gym Y costs $15m + 3(8)m = 39m$. Gym X is cheaper when $40 + 25m < 39m$, so $40 < 14m$ and $m > 2.86$. The least whole number is 3. (Check: after 2 months X costs 90 and Y costs 78; after 3 months X costs 115 and Y costs 117.)"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='dde5eb38-0a93-c316-14f0-cfe02f27fc03') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4874fa9a-3a95-2771-9a60-1e8b2239fba4','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"$$y > 2x - 6$$ $$y \\le -3x + 19$$ The point $(a, 4)$ is a solution to the system of inequalities. What is the greatest possible integer value of $a$?"}'::jsonb,108,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-020","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4874fa9a-3a95-2771-9a60-1e8b2239fba4','{"accepted":["4"]}'::jsonb,'{"feedback":{"explanation":"Substitute $y = 4$. The first inequality gives $4 > 2a - 6$, so $a < 5$. The second gives $4 \\le -3a + 19$, so $a \\le 5$. Both hold when $a < 5$, so the greatest integer is 4. A common error is to answer 5, which satisfies the second inequality but not the strict first one."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4874fa9a-3a95-2771-9a60-1e8b2239fba4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f00e315f-c263-db20-9b93-8aed7336dca4','d2115786-810b-dbc1-4189-4d054f8f9581','question_spr','{"prompt":"$$y \\le -x + 9$$ $$y \\le x + 3$$ In the xy-plane, the point $(x, y)$ satisfies the system of inequalities. What is the maximum possible value of $y$?"}'::jsonb,109,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-021","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f00e315f-c263-db20-9b93-8aed7336dca4','{"accepted":["6"]}'::jsonb,'{"feedback":{"explanation":"Both inequalities bound $y$ from above, so $y$ is largest where the two boundary lines meet. Setting $-x + 9 = x + 3$ gives $x = 3$, and then $y = 6$. For any other $x$, one of the two bounds is smaller than 6, so the maximum value of $y$ is 6."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f00e315f-c263-db20-9b93-8aed7336dca4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bf92cf87-d70f-af92-18f8-a14e93484458','d2115786-810b-dbc1-4189-4d054f8f9581','question_single_choice','{"prompt":"A delivery van can carry a total of at most 1,200 kilograms, including its 85-kilogram driver. The driver loads 15 boxes that weigh 32 kilograms each. What is the greatest number of 25-kilogram boxes that can also be loaded?","options":[{"id":"A","label":"$25$"},{"id":"B","label":"$26$"},{"id":"C","label":"$28$"},{"id":"D","label":"$44$"}]}'::jsonb,110,'{"section_type":"math","sat_domain":"algebra","sat_official_domain":"algebra","sat_skill":"linear_inequalities","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"alg-ineq-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'bf92cf87-d70f-af92-18f8-a14e93484458','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The total weight must satisfy $85 + 32(15) + 25y \\le 1{,}200$, so $565 + 25y \\le 1{,}200$, $25y \\le 635$, and $y \\le 25.4$. The greatest whole number is 25. Choice B rounds 25.4 up, which would exceed the limit. Choice D ignores the 15 heavier boxes. Choice C ignores the driver''s 85 kilograms."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='bf92cf87-d70f-af92-18f8-a14e93484458') on conflict do nothing;
insert into public.parts(id,section_id,name,display_order) values('20dc549c-274c-938f-fb11-e72eb65b2a6e','bee41358-7368-5bbb-bb76-e42afe3c1c44','Advanced Math',11) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('da22db54-fe1d-52aa-ce3b-6a0e4e3710b8','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $(3x^2 + 5x - 2) + (x^2 - 7x + 4)$?","options":[{"id":"A","label":"$4x^4 - 2x^2 + 2$"},{"id":"B","label":"$4x^2 + 12x + 2$"},{"id":"C","label":"$4x^2 - 2x - 6$"},{"id":"D","label":"$4x^2 - 2x + 2$"}]}'::jsonb,1,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'da22db54-fe1d-52aa-ce3b-6a0e4e3710b8','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Combine like terms: $3x^2 + x^2 = 4x^2$, $5x - 7x = -2x$, and $-2 + 4 = 2$, giving $4x^2 - 2x + 2$. Choice B adds 7 instead of $-7$ to the $x$-coefficient. Choice C subtracts 4 instead of adding it. Choice A adds the exponents when combining like terms; exponents do not change when like terms are added."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='da22db54-fe1d-52aa-ce3b-6a0e4e3710b8') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ddb8fa6e-41e9-6a36-62e1-02a2949f59b6','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $(2x - 3)(x + 4)$?","options":[{"id":"A","label":"$2x^2 - 12$"},{"id":"B","label":"$2x^2 - 5x - 12$"},{"id":"C","label":"$2x^2 + 11x - 12$"},{"id":"D","label":"$2x^2 + 5x - 12$"}]}'::jsonb,2,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ddb8fa6e-41e9-6a36-62e1-02a2949f59b6','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Distribute: $2x \\cdot x + 2x \\cdot 4 - 3 \\cdot x - 3 \\cdot 4 = 2x^2 + 8x - 3x - 12 = 2x^2 + 5x - 12$. Choice A multiplies only the first terms and the last terms and leaves out the middle terms. Choice C adds $3x$ instead of subtracting it. Choice B has the sign of the middle term reversed, as if the factors were $(2x + 3)(x - 4)$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ddb8fa6e-41e9-6a36-62e1-02a2949f59b6') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('102bfe75-fbb7-3742-7ad6-6f7a666c3e1c','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $4x(3x - 5) - 2x^2$?","options":[{"id":"A","label":"$10x^2 - 5x$"},{"id":"B","label":"$12x^2 - 22x$"},{"id":"C","label":"$14x^2 - 20x$"},{"id":"D","label":"$10x^2 - 20x$"}]}'::jsonb,3,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '102bfe75-fbb7-3742-7ad6-6f7a666c3e1c','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Distribute: $4x(3x - 5) = 12x^2 - 20x$. Subtracting $2x^2$ gives $10x^2 - 20x$. Choice A multiplies $-5$ by $x$ instead of by $4x$. Choice B combines $-2x^2$ with $-20x$, which are not like terms. Choice C adds $2x^2$ instead of subtracting it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='102bfe75-fbb7-3742-7ad6-6f7a666c3e1c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e2714b6f-db4f-25e1-ecdf-b7015826fb26','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $x^2 - 9x + 20$?","options":[{"id":"A","label":"$(x + 4)(x + 5)$"},{"id":"B","label":"$(x - 2)(x - 10)$"},{"id":"C","label":"$(x - 4)(x + 5)$"},{"id":"D","label":"$(x - 4)(x - 5)$"}]}'::jsonb,4,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e2714b6f-db4f-25e1-ecdf-b7015826fb26','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Look for two numbers with product 20 and sum $-9$: they are $-4$ and $-5$, so $x^2 - 9x + 20 = (x - 4)(x - 5)$. Choice A gives a middle term of $+9x$. Choice B has product 20 but sum $-12$. Choice C has product $-20$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e2714b6f-db4f-25e1-ecdf-b7015826fb26') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9c770eb7-b35f-a60f-1a4f-88414363a3dd','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x \\neq 0$, which expression is equivalent to $\\frac{12x^5}{3x^2}$?","options":[{"id":"A","label":"$4x^{\\frac{5}{2}}$"},{"id":"B","label":"$9x^3$"},{"id":"C","label":"$4x^7$"},{"id":"D","label":"$4x^3$"}]}'::jsonb,5,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9c770eb7-b35f-a60f-1a4f-88414363a3dd','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Divide the coefficients and subtract the exponents: $\\frac{12}{3} = 4$ and $x^{5 - 2} = x^3$, so the expression is $4x^3$. Choice B subtracts the coefficients. Choice C adds the exponents, which is the rule for multiplication. Choice A divides the exponents."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9c770eb7-b35f-a60f-1a4f-88414363a3dd') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('87bf6867-c220-5574-cbb0-f07bbc9f399b','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $(x^3)^4 \\cdot x^2$?","options":[{"id":"A","label":"$x^9$"},{"id":"B","label":"$x^{14}$"},{"id":"C","label":"$x^{12}$"},{"id":"D","label":"$x^{24}$"}]}'::jsonb,6,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '87bf6867-c220-5574-cbb0-f07bbc9f399b','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"A power of a power multiplies exponents: $(x^3)^4 = x^{12}$. Multiplying by $x^2$ adds exponents: $x^{12 + 2} = x^{14}$. Choice A adds all three exponents. Choice C leaves out the factor $x^2$. Choice D multiplies all three exponents."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='87bf6867-c220-5574-cbb0-f07bbc9f399b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fc2e3705-ebd2-14b9-f97a-933f63cb438b','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The expression $(x + 6)^2$ is equivalent to $x^2 + bx + 36$, where $b$ is a constant. What is the value of $b$?"}'::jsonb,7,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-007","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fc2e3705-ebd2-14b9-f97a-933f63cb438b','{"accepted":["12"]}'::jsonb,'{"feedback":{"explanation":"$(x + 6)^2 = (x + 6)(x + 6) = x^2 + 6x + 6x + 36 = x^2 + 12x + 36$, so $b = 12$. A common mistake is to write $(x + 6)^2 = x^2 + 36$, which leaves out the middle term."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fc2e3705-ebd2-14b9-f97a-933f63cb438b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dd729ffc-3494-7722-c59a-29ed0d397527','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $9x^2 - 25$?","options":[{"id":"A","label":"$(3x - 5)^2$"},{"id":"B","label":"$(3x - 25)(3x + 1)$"},{"id":"C","label":"$(9x - 5)(x + 5)$"},{"id":"D","label":"$(3x - 5)(3x + 5)$"}]}'::jsonb,8,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'dd729ffc-3494-7722-c59a-29ed0d397527','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"$9x^2 - 25$ is a difference of squares, $(3x)^2 - 5^2$, which factors as $(3x - 5)(3x + 5)$. Choice A expands to $9x^2 - 30x + 25$. Choice C expands to $9x^2 + 40x - 25$. Choice B expands to $9x^2 - 72x - 25$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='dd729ffc-3494-7722-c59a-29ed0d397527') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('152f4481-ea4d-7e7e-78b6-c18d3cb1f391','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $(5x^2 - 2x + 1) - (3x^2 + 4x - 6)$?","options":[{"id":"A","label":"$2x^2 + 2x - 5$"},{"id":"B","label":"$2x^2 - 6x - 5$"},{"id":"C","label":"$2x^2 + 2x + 7$"},{"id":"D","label":"$2x^2 - 6x + 7$"}]}'::jsonb,9,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '152f4481-ea4d-7e7e-78b6-c18d3cb1f391','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Distribute the subtraction to every term: $5x^2 - 2x + 1 - 3x^2 - 4x + 6 = 2x^2 - 6x + 7$. Choice A subtracts only the first term and adds the others. Choice B subtracts $-6$ incorrectly, getting $-5$. Choice C changes the constant correctly but adds $4x$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='152f4481-ea4d-7e7e-78b6-c18d3cb1f391') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('09911ce3-2e2c-c799-cda9-e4cb35fa4ca0','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The area $A$ of a trapezoid with height $h$ and parallel sides of lengths $b_1$ and $b_2$ is given by $A = \\frac{1}{2}h(b_1 + b_2)$. Which equation correctly expresses $h$ in terms of $A$, $b_1$, and $b_2$?","options":[{"id":"A","label":"$h = \\frac{2A}{b_1 + b_2}$"},{"id":"B","label":"$h = \\frac{A}{2(b_1 + b_2)}$"},{"id":"C","label":"$h = 2A - (b_1 + b_2)$"},{"id":"D","label":"$h = \\frac{b_1 + b_2}{2A}$"}]}'::jsonb,10,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '09911ce3-2e2c-c799-cda9-e4cb35fa4ca0','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Multiply both sides by 2: $2A = h(b_1 + b_2)$. Divide by $b_1 + b_2$: $h = \\frac{2A}{b_1 + b_2}$. Choice B divides by 2 instead of multiplying by 2. Choice C subtracts $b_1 + b_2$, but it multiplies $h$ and must be removed by division. Choice D is the reciprocal of the correct expression."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='09911ce3-2e2c-c799-cda9-e4cb35fa4ca0') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3cb929de-3e02-817e-8dcc-671c8c3328a9','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x > 0$, which expression is equivalent to $\\sqrt[3]{x^2}$?","options":[{"id":"A","label":"$x^{\\frac{3}{2}}$"},{"id":"B","label":"$x^{\\frac{2}{3}}$"},{"id":"C","label":"$x^{6}$"},{"id":"D","label":"$x^{-1}$"}]}'::jsonb,11,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3cb929de-3e02-817e-8dcc-671c8c3328a9','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The cube root is the $\\frac{1}{3}$ power, so $\\sqrt[3]{x^2} = (x^2)^{\\frac{1}{3}} = x^{\\frac{2}{3}}$. Choice A puts the root index in the numerator. Choice C multiplies 2 and 3. Choice D subtracts 3 from 2."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3cb929de-3e02-817e-8dcc-671c8c3328a9') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('078de128-8bdd-ab5d-bf50-278e9bfe5b2c','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"For $x \\neq 4$, the expression $\\frac{x^2 - 16}{x - 4}$ is equivalent to $x + k$, where $k$ is a constant. What is the value of $k$?"}'::jsonb,12,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-012","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '078de128-8bdd-ab5d-bf50-278e9bfe5b2c','{"accepted":["4"]}'::jsonb,'{"feedback":{"explanation":"Factor the numerator as a difference of squares: $x^2 - 16 = (x - 4)(x + 4)$. Dividing by $x - 4$ leaves $x + 4$, so $k = 4$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='078de128-8bdd-ab5d-bf50-278e9bfe5b2c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e1a0ada8-10d9-1f7c-07fe-8def1bb0b4a2','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The expression $2(3x - 4) + 5(x + 2)$ is equivalent to $ax + b$, where $a$ and $b$ are constants. What is the value of $a + b$?"}'::jsonb,13,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-013","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e1a0ada8-10d9-1f7c-07fe-8def1bb0b4a2','{"accepted":["13"]}'::jsonb,'{"feedback":{"explanation":"Distribute: $6x - 8 + 5x + 10 = 11x + 2$. So $a = 11$, $b = 2$, and $a + b = 13$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e1a0ada8-10d9-1f7c-07fe-8def1bb0b4a2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1fd934cc-d3f6-5f8b-8dde-02e87524b6ff','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $(2x + 3)^2 - (2x - 3)^2$?","options":[{"id":"A","label":"$0$"},{"id":"B","label":"$12x$"},{"id":"C","label":"$24x$"},{"id":"D","label":"$8x^2 + 18$"}]}'::jsonb,14,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1fd934cc-d3f6-5f8b-8dde-02e87524b6ff','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Expand: $(4x^2 + 12x + 9) - (4x^2 - 12x + 9) = 24x$. Choice A assumes the squares cancel completely, ignoring the middle terms of opposite sign. Choice B counts the middle term $12x$ only once. Choice D adds the two squares instead of subtracting them."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1fd934cc-d3f6-5f8b-8dde-02e87524b6ff') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('31186b56-92a3-603e-8aed-06ada56db9d1','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x \\neq -3$, which expression is equivalent to $\\frac{x^2 + 5x + 6}{x + 3}$?","options":[{"id":"A","label":"$x - 2$"},{"id":"B","label":"$x^2 + 5x + 2$"},{"id":"C","label":"$x + 3$"},{"id":"D","label":"$x + 2$"}]}'::jsonb,15,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '31186b56-92a3-603e-8aed-06ada56db9d1','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Factor the numerator: $x^2 + 5x + 6 = (x + 2)(x + 3)$. Dividing by $x + 3$ leaves $x + 2$. Choice A has the wrong sign. Choice C is the canceled factor. Choice B \\\"cancels\\\" the 3 from the denominator with part of the 6, which is not a valid operation."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='31186b56-92a3-603e-8aed-06ada56db9d1') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bdf19285-4de2-9e98-ed8b-7a37f457a890','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x > 0$, which expression is equivalent to $x^{-2} \\cdot x^{\\frac{5}{2}}$?","options":[{"id":"A","label":"$\\sqrt{x}$"},{"id":"B","label":"$\\frac{1}{\\sqrt{x}}$"},{"id":"C","label":"$x^{\\frac{9}{2}}$"},{"id":"D","label":"$x^{-5}$"}]}'::jsonb,16,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'bdf19285-4de2-9e98-ed8b-7a37f457a890','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Add the exponents: $-2 + \\frac{5}{2} = \\frac{1}{2}$, so the product is $x^{\\frac{1}{2}} = \\sqrt{x}$. Choice D multiplies the exponents. Choice B gets $-\\frac{1}{2}$ by subtracting in the wrong order. Choice C ignores the negative sign on $-2$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='bdf19285-4de2-9e98-ed8b-7a37f457a890') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bbd98ca8-06b0-9721-05e2-1cb41cb41f8a','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x > 0$, which expression is equivalent to $\\frac{3}{x} + \\frac{2}{x + 1}$?","options":[{"id":"A","label":"$\\frac{5}{2x + 1}$"},{"id":"B","label":"$\\frac{5x + 3}{x(x + 1)}$"},{"id":"C","label":"$\\frac{5x + 1}{x(x + 1)}$"},{"id":"D","label":"$\\frac{6}{x(x + 1)}$"}]}'::jsonb,17,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'bbd98ca8-06b0-9721-05e2-1cb41cb41f8a','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Use the common denominator $x(x + 1)$: $\\frac{3(x + 1) + 2x}{x(x + 1)} = \\frac{5x + 3}{x(x + 1)}$. Choice A adds the numerators and the denominators separately. Choice C writes $3(x + 1)$ as $3x + 1$. Choice D multiplies the numerators instead of rewriting each fraction over the common denominator."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='bbd98ca8-06b0-9721-05e2-1cb41cb41f8a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0d9097d8-0ec8-f376-89f5-51fb515d83a7','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The speed $v$ of an object with mass $m$ and kinetic energy $E$ satisfies $v = \\sqrt{\\frac{2E}{m}}$, where $m > 0$ and $v > 0$. Which equation gives $m$ in terms of $E$ and $v$?","options":[{"id":"A","label":"$m = \\frac{2E}{v}$"},{"id":"B","label":"$m = \\frac{v^2}{2E}$"},{"id":"C","label":"$m = \\frac{2E}{v^2}$"},{"id":"D","label":"$m = 2Ev^2$"}]}'::jsonb,18,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0d9097d8-0ec8-f376-89f5-51fb515d83a7','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Square both sides: $v^2 = \\frac{2E}{m}$. Multiply by $m$ and divide by $v^2$: $m = \\frac{2E}{v^2}$. Choice A forgets to square $v$ when removing the square root. Choice B inverts the fraction. Choice D multiplies by $v^2$ instead of dividing."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0d9097d8-0ec8-f376-89f5-51fb515d83a7') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c98ee651-8111-2c95-5ca7-af4437639798','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The expression $(3x - 2)(ax + 5)$, where $a$ is a constant, is equivalent to $6x^2 + bx - 10$, where $b$ is a constant. What is the value of $b$?"}'::jsonb,19,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-019","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c98ee651-8111-2c95-5ca7-af4437639798','{"accepted":["11"]}'::jsonb,'{"feedback":{"explanation":"The $x^2$-coefficient of the product is $3a$, so $3a = 6$ and $a = 2$. Then $(3x - 2)(2x + 5) = 6x^2 + 15x - 4x - 10 = 6x^2 + 11x - 10$, so $b = 11$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c98ee651-8111-2c95-5ca7-af4437639798') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d01be6a8-eede-5a99-2e8d-7efa1ba58c65','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The expression $x^2 + 10x + 7$ can be written in the form $(x + h)^2 + k$, where $h$ and $k$ are constants. What is the value of $k$?"}'::jsonb,20,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-020","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'd01be6a8-eede-5a99-2e8d-7efa1ba58c65','{"accepted":["-18"]}'::jsonb,'{"feedback":{"explanation":"Complete the square: $x^2 + 10x = (x + 5)^2 - 25$. So $x^2 + 10x + 7 = (x + 5)^2 - 25 + 7 = (x + 5)^2 - 18$, and $k = -18$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='d01be6a8-eede-5a99-2e8d-7efa1ba58c65') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('711509bf-d32a-d8a2-cf11-5fc4d45d2525','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"If $a = 3b - 2$, which expression is equivalent to $9b^2 - 12b + 4$?","options":[{"id":"A","label":"$a^2 - 4$"},{"id":"B","label":"$a^2 + 4$"},{"id":"C","label":"$(a - 2)^2$"},{"id":"D","label":"$a^2$"}]}'::jsonb,21,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '711509bf-d32a-d8a2-cf11-5fc4d45d2525','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Notice that $9b^2 - 12b + 4 = (3b - 2)^2$, a perfect square. Since $3b - 2 = a$, the expression equals $a^2$. Choice A treats $(3b - 2)^2$ as $9b^2 - 4$. Choice C replaces $3b$ with $a$ instead of replacing $3b - 2$ with $a$. Choice B treats $9b^2 - 12b$ as $a^2$ and then adds the 4 again."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='711509bf-d32a-d8a2-cf11-5fc4d45d2525') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1feff16c-f92e-db2d-75cf-0009d58592fc','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"For $x \\neq -4$, the expression $\\frac{2x^2 + 7x - 3}{x + 4}$ is equivalent to $2x - 1 + \\frac{A}{x + 4}$, where $A$ is a constant. What is the value of $A$?"}'::jsonb,22,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-022","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1feff16c-f92e-db2d-75cf-0009d58592fc','{"accepted":["1"]}'::jsonb,'{"feedback":{"explanation":"Multiply $2x - 1 + \\frac{A}{x + 4}$ by $x + 4$: $(2x - 1)(x + 4) + A = 2x^2 + 7x - 4 + A$. This must equal $2x^2 + 7x - 3$, so $A = 1$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1feff16c-f92e-db2d-75cf-0009d58592fc') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d7e9cdd6-3b36-d197-9f80-1518291d933d','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x > 0$ and $y > 0$, which expression is equivalent to $(x^2 y^3)^2 (x y^{-1})^3$?","options":[{"id":"A","label":"$x^7 y^3$"},{"id":"B","label":"$x^7 y^9$"},{"id":"C","label":"$x^{12} y^{-18}$"},{"id":"D","label":"$x^4 y^6$"}]}'::jsonb,23,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'd7e9cdd6-3b36-d197-9f80-1518291d933d','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Apply each power: $(x^2y^3)^2 = x^4y^6$ and $(xy^{-1})^3 = x^3y^{-3}$. Multiply by adding exponents: $x^{4 + 3}y^{6 - 3} = x^7y^3$. Choice D stops after the first factor. Choice B drops the negative sign on $-3$. Choice C multiplies the exponents of the two factors instead of adding them."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='d7e9cdd6-3b36-d197-9f80-1518291d933d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4b30a1b9-7e61-7dc1-5aaa-bf3050728525','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $2x^2 - x - 15$?","options":[{"id":"A","label":"$(2x - 5)(x + 3)$"},{"id":"B","label":"$(2x + 5)(x - 3)$"},{"id":"C","label":"$(2x + 3)(x - 5)$"},{"id":"D","label":"$(2x - 3)(x + 5)$"}]}'::jsonb,24,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-024","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4b30a1b9-7e61-7dc1-5aaa-bf3050728525','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Expand each choice and compare the middle term. $(2x + 5)(x - 3) = 2x^2 - 6x + 5x - 15 = 2x^2 - x - 15$. Choice A gives $2x^2 + x - 15$, the wrong sign. Choice C gives $2x^2 - 7x - 15$. Choice D gives $2x^2 + 7x - 15$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4b30a1b9-7e61-7dc1-5aaa-bf3050728525') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1a6c10ce-0863-10a6-c02d-d6e1126905c9','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"An account balance $A$ after $t$ years of annual compound interest is given by $A = P(1 + r)^t$, where $P$ is the initial deposit and $r$ is the annual interest rate written as a decimal. Which equation expresses $P$ in terms of $A$, $r$, and $t$?","options":[{"id":"A","label":"$P = A(1 + r)^t$"},{"id":"B","label":"$P = \\frac{A}{1 + rt}$"},{"id":"C","label":"$P = \\frac{A}{(1 + r)^t}$"},{"id":"D","label":"$P = A - (1 + r)^t$"}]}'::jsonb,25,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-025","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1a6c10ce-0863-10a6-c02d-d6e1126905c9','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"$P$ is multiplied by $(1 + r)^t$, so divide both sides by $(1 + r)^t$: $P = \\frac{A}{(1 + r)^t}$. Choice A multiplies instead of dividing. Choice B replaces the exponent $t$ with multiplication, which describes simple interest. Choice D subtracts a factor instead of dividing by it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1a6c10ce-0863-10a6-c02d-d6e1126905c9') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c510d4f8-b957-a6cd-d944-e39094c1075e','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x > 0$, which expression is equivalent to $\\sqrt{50x^3}$?","options":[{"id":"A","label":"$5x\\sqrt{2}$"},{"id":"B","label":"$25x\\sqrt{2x}$"},{"id":"C","label":"$5x^2\\sqrt{2x}$"},{"id":"D","label":"$5x\\sqrt{2x}$"}]}'::jsonb,26,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-026","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c510d4f8-b957-a6cd-d944-e39094c1075e','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Write $50x^3 = 25x^2 \\cdot 2x$. Then $\\sqrt{25x^2 \\cdot 2x} = 5x\\sqrt{2x}$. Choice B takes 25 out of the root without taking its square root. Choice C takes $x^2$ out unchanged instead of $x$. Choice A leaves the remaining factor of $x$ out of the radicand."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c510d4f8-b957-a6cd-d944-e39094c1075e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9aa69dd7-bf69-a97a-0b33-07ae4fc48bd9','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The expression $4x^2 - 20x + 25$ is equivalent to $(ax + b)^2$, where $a$ and $b$ are constants and $a > 0$. What is the value of $ab$?"}'::jsonb,27,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-027","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9aa69dd7-bf69-a97a-0b33-07ae4fc48bd9','{"accepted":["-10"]}'::jsonb,'{"feedback":{"explanation":"Since $4x^2 = (2x)^2$ and $25 = 5^2$, try $(2x - 5)^2 = 4x^2 - 20x + 25$. The middle term matches, so $a = 2$, $b = -5$, and $ab = -10$. (Choosing $b = 5$ would give a middle term of $+20x$.)"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9aa69dd7-bf69-a97a-0b33-07ae4fc48bd9') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4836e820-37e1-4513-a370-efb4badc8316','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x \\neq 3$ and $x \\neq -3$, which expression is equivalent to $\\frac{x}{x - 3} - \\frac{18}{x^2 - 9}$?","options":[{"id":"A","label":"$\\frac{x + 6}{x + 3}$"},{"id":"B","label":"$\\frac{x - 18}{x^2 - 9}$"},{"id":"C","label":"$\\frac{x + 6}{x - 3}$"},{"id":"D","label":"$\\frac{x - 6}{x + 3}$"}]}'::jsonb,28,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-028","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4836e820-37e1-4513-a370-efb4badc8316','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Rewrite the first fraction over $x^2 - 9 = (x - 3)(x + 3)$: $\\frac{x(x + 3) - 18}{(x - 3)(x + 3)} = \\frac{x^2 + 3x - 18}{(x - 3)(x + 3)} = \\frac{(x + 6)(x - 3)}{(x - 3)(x + 3)} = \\frac{x + 6}{x + 3}$. Choice D factors $x^2 + 3x - 18$ with the wrong signs. Choice B subtracts the numerators without first multiplying $x$ by $x + 3$. Choice C cancels the wrong factor."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4836e820-37e1-4513-a370-efb4badc8316') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dbc4d079-9b1e-06eb-2897-4088f57c3b67','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The expression $(ax + 3)(bx - 5)$, where $a$ and $b$ are positive integer constants, is equivalent to $12x^2 - 11x - 15$. What is the value of $a + b$?"}'::jsonb,29,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-029","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'dbc4d079-9b1e-06eb-2897-4088f57c3b67','{"accepted":["7"]}'::jsonb,'{"feedback":{"explanation":"Expanding gives $abx^2 + (3b - 5a)x - 15$. So $ab = 12$ and $3b - 5a = -11$. Test the positive factor pairs of 12: $(a, b) = (4, 3)$ gives $3(3) - 5(4) = -11$, and no other pair works (for example, $(3, 4)$ gives $-3$). So $a + b = 7$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='dbc4d079-9b1e-06eb-2897-4088f57c3b67') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fa766310-1228-104b-a426-2e6ee5f2b30d','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x \\neq 2$, which expression is equivalent to $\\frac{x^3 - 8}{x - 2}$?","options":[{"id":"A","label":"$x^2 + 4$"},{"id":"B","label":"$x^2 + 2x + 4$"},{"id":"C","label":"$x^2 - 2x + 4$"},{"id":"D","label":"$x^2 + 4x + 4$"}]}'::jsonb,30,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-030","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fa766310-1228-104b-a426-2e6ee5f2b30d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"$x^3 - 8$ is a difference of cubes: $x^3 - 2^3 = (x - 2)(x^2 + 2x + 4)$. Dividing by $x - 2$ leaves $x^2 + 2x + 4$. Choice A divides term by term, which is not valid. Choice C is the factor that appears in a sum of cubes, $x^3 + 8$. Choice D is $(x + 2)^2$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fa766310-1228-104b-a426-2e6ee5f2b30d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7bf1829a-57cc-55ad-3478-290b71ed50f4','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"If $x^2 + y^2 = 29$ and $xy = 10$, what is the value of $(x - y)^2$?"}'::jsonb,31,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-031","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '7bf1829a-57cc-55ad-3478-290b71ed50f4','{"accepted":["9"]}'::jsonb,'{"feedback":{"explanation":"Expand: $(x - y)^2 = x^2 - 2xy + y^2 = (x^2 + y^2) - 2xy = 29 - 2(10) = 9$. There is no need to find $x$ and $y$ individually."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='7bf1829a-57cc-55ad-3478-290b71ed50f4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3e27612c-c84e-3b28-fdc1-f18c6639dec2','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x > 0$ and $y > 0$, which expression is equivalent to $\\left(\\frac{27x^6}{y^3}\\right)^{-\\frac{2}{3}}$?","options":[{"id":"A","label":"$\\frac{9x^4}{y^2}$"},{"id":"B","label":"$\\frac{y^2}{18x^4}$"},{"id":"C","label":"$\\frac{y^2}{9x^4}$"},{"id":"D","label":"$\\frac{1}{9x^4y^2}$"}]}'::jsonb,32,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-032","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3e27612c-c84e-3b28-fdc1-f18c6639dec2','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"A negative exponent inverts the base: $\\left(\\frac{y^3}{27x^6}\\right)^{\\frac{2}{3}}$. Then $(y^3)^{\\frac{2}{3}} = y^2$, $27^{\\frac{2}{3}} = (\\sqrt[3]{27})^2 = 9$, and $(x^6)^{\\frac{2}{3}} = x^4$, giving $\\frac{y^2}{9x^4}$. Choice A ignores the negative sign. Choice B computes $27^{\\frac{2}{3}}$ as $27 \\times \\frac{2}{3} = 18$. Choice D applies the negative sign to $y$ twice, leaving $y$ in the denominator."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3e27612c-c84e-3b28-fdc1-f18c6639dec2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('80dd4b30-36e0-192c-8237-847f67b4abb1','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which of the following is the complete factorization of $x^4 - 13x^2 + 36$?","options":[{"id":"A","label":"$(x - 4)(x + 4)(x - 9)(x + 9)$"},{"id":"B","label":"$(x - 2)^2(x - 3)^2$"},{"id":"C","label":"$(x^2 + 4)(x^2 + 9)$"},{"id":"D","label":"$(x - 2)(x + 2)(x - 3)(x + 3)$"}]}'::jsonb,33,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-033","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '80dd4b30-36e0-192c-8237-847f67b4abb1','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Treat the expression as a quadratic in $x^2$: $x^4 - 13x^2 + 36 = (x^2 - 4)(x^2 - 9)$, since $4 \\cdot 9 = 36$ and $4 + 9 = 13$. Each factor is a difference of squares, so the complete factorization is $(x - 2)(x + 2)(x - 3)(x + 3)$. Choice A uses 4 and 9 where their square roots belong. Choice B expands to an expression with odd powers of $x$. Choice C has the wrong signs and expands to $x^4 + 13x^2 + 36$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='80dd4b30-36e0-192c-8237-847f67b4abb1') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e2ee313a-529b-fa8d-cc74-f03b7368c174','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"For $x > 0$, the expression $\\sqrt[3]{x^5} \\cdot \\sqrt{x}$ is equivalent to $x^k$. What is the value of $k$?"}'::jsonb,34,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-034","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e2ee313a-529b-fa8d-cc74-f03b7368c174','{"accepted":["13/6","2.166","2.167"]}'::jsonb,'{"feedback":{"explanation":"Write each root as a power: $\\sqrt[3]{x^5} = x^{\\frac{5}{3}}$ and $\\sqrt{x} = x^{\\frac{1}{2}}$. Multiplying adds the exponents: $\\frac{5}{3} + \\frac{1}{2} = \\frac{10}{6} + \\frac{3}{6} = \\frac{13}{6}$. Enter 13/6, 2.166, or 2.167."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e2ee313a-529b-fa8d-cc74-f03b7368c174') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('007ae8a9-73e2-7c67-3f33-70852a1df269','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"Which expression is equivalent to $(16^x)^{\\frac{1}{2}} \\cdot 2^x$?","options":[{"id":"A","label":"$8^x$"},{"id":"B","label":"$2^{5x}$"},{"id":"C","label":"$2^{\\frac{5x}{2}}$"},{"id":"D","label":"$32^x$"}]}'::jsonb,35,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-035","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '007ae8a9-73e2-7c67-3f33-70852a1df269','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"$(16^x)^{\\frac{1}{2}} = 16^{\\frac{x}{2}} = (2^4)^{\\frac{x}{2}} = 2^{2x}$. Multiplying by $2^x$ gives $2^{3x} = (2^3)^x = 8^x$. Choice B ignores the exponent $\\frac{1}{2}$ and adds $4x + x$. Choice C applies the exponent $\\frac{1}{2}$ to the factor $2^x$ as well, computing $(16^x \\cdot 2^x)^{\\frac{1}{2}}$. Choice D multiplies the bases, $16 \\cdot 2 = 32$, without applying the exponent $\\frac{1}{2}$ to 16."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='007ae8a9-73e2-7c67-3f33-70852a1df269') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('31edc66e-91c7-da1a-50e2-f24a08288397','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For $x > 1$, which expression is equivalent to $\\frac{x - 1}{\\sqrt{x} + 1}$?","options":[{"id":"A","label":"$\\sqrt{x} + 1$"},{"id":"B","label":"$\\sqrt{x} - 1$"},{"id":"C","label":"$x - 2$"},{"id":"D","label":"$\\frac{x - 1}{\\sqrt{x}}$"}]}'::jsonb,36,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"equivalent_expressions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-equiv-036","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '31edc66e-91c7-da1a-50e2-f24a08288397','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Factor the numerator as a difference of squares: $x - 1 = (\\sqrt{x})^2 - 1^2 = (\\sqrt{x} - 1)(\\sqrt{x} + 1)$. Dividing by $\\sqrt{x} + 1$ leaves $\\sqrt{x} - 1$. Choice A is the canceled factor. Choice C subtracts 1 in the denominator from the numerator, which is not valid for division. Choice D cancels only the 1 in the denominator."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='31edc66e-91c7-da1a-50e2-f24a08288397') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2922a51d-d1b7-172c-c524-08c74c6611f8','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"If $3x^2 = 75$ and $x > 0$, what is the value of $x$?","options":[{"id":"A","label":"$5$"},{"id":"B","label":"$5\\sqrt{3}$"},{"id":"C","label":"$25$"},{"id":"D","label":"$72$"}]}'::jsonb,37,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '2922a51d-d1b7-172c-c524-08c74c6611f8','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Divide by 3: $x^2 = 25$. Since $x > 0$, $x = 5$. Choice C is the value of $x^2$; the square root still has to be taken. Choice B takes the square root of 75 without first dividing by 3. Choice D subtracts 3 instead of dividing by it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='2922a51d-d1b7-172c-c524-08c74c6611f8') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c31041c2-817a-2e39-1d6d-2ad63e9362f4','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What are the solutions to the equation $(x - 3)(x + 5) = 0$?","options":[{"id":"A","label":"$-3$ and $5$"},{"id":"B","label":"$3$ and $5$"},{"id":"C","label":"$3$ and $-5$"},{"id":"D","label":"$-15$ only"}]}'::jsonb,38,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c31041c2-817a-2e39-1d6d-2ad63e9362f4','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"A product is zero when one of its factors is zero: $x - 3 = 0$ gives $x = 3$, and $x + 5 = 0$ gives $x = -5$. Choice A reverses both signs. Choice B reverses the sign of the second solution. Choice D multiplies the constants, which gives the constant term of the expanded equation, not a solution."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c31041c2-817a-2e39-1d6d-2ad63e9362f4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c8eb96c5-a9c0-aa6e-fb54-d935226760e4','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"What value of $x$ satisfies the equation $\\sqrt{x + 4} = 5$?"}'::jsonb,39,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-003","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c8eb96c5-a9c0-aa6e-fb54-d935226760e4','{"accepted":["21"]}'::jsonb,'{"feedback":{"explanation":"Square both sides: $x + 4 = 25$, so $x = 21$. Check: $\\sqrt{25} = 5$. A common error is to forget to square the 5, which gives $x = 1$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c8eb96c5-a9c0-aa6e-fb54-d935226760e4') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e51319b6-b7fe-6589-74e4-d5846452ce5b','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What is the sum of the solutions to $x^2 - 6x + 8 = 0$?","options":[{"id":"A","label":"$-6$"},{"id":"B","label":"$2$"},{"id":"C","label":"$6$"},{"id":"D","label":"$8$"}]}'::jsonb,40,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e51319b6-b7fe-6589-74e4-d5846452ce5b','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Factor: $(x - 2)(x - 4) = 0$, so the solutions are 2 and 4, and their sum is 6. Choice A has the wrong sign (the sum is the opposite of the $x$-coefficient). Choice B is only one of the solutions. Choice D is the product of the solutions."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e51319b6-b7fe-6589-74e4-d5846452ce5b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fa29be71-42b6-8d90-d8d9-3514399ab4ef','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What are all the solutions to $x^2 + 4x = 0$?","options":[{"id":"A","label":"$-4$ only"},{"id":"B","label":"$0$ and $4$"},{"id":"C","label":"$4$ only"},{"id":"D","label":"$0$ and $-4$"}]}'::jsonb,41,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fa29be71-42b6-8d90-d8d9-3514399ab4ef','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Factor out $x$: $x(x + 4) = 0$, so $x = 0$ or $x = -4$. Choice A divides both sides by $x$, which loses the solution $x = 0$. Choice B and choice C have the wrong sign for the nonzero solution."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fa29be71-42b6-8d90-d8d9-3514399ab4ef') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a29fd87a-6422-0e45-082f-730541d3d5b8','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"A ball is dropped from a height of 45 meters. Its height $h$, in meters, $t$ seconds after it is dropped is modeled by $h = -5t^2 + 45$. How many seconds after it is dropped does the ball reach the ground?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$3\\sqrt{5}$"},{"id":"C","label":"$9$"},{"id":"D","label":"$45$"}]}'::jsonb,42,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a29fd87a-6422-0e45-082f-730541d3d5b8','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The ball reaches the ground when $h = 0$: $-5t^2 + 45 = 0$, so $t^2 = 9$ and $t = 3$ (time must be positive). Choice C is $t^2$. Choice B takes the square root of 45 without dividing by 5. Choice D is the starting height."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a29fd87a-6422-0e45-082f-730541d3d5b8') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b7ba0427-02e4-1f4f-0c2d-bb5e4fa107b6','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What value of $x$ satisfies $2^{x + 1} = 32$?","options":[{"id":"A","label":"$4$"},{"id":"B","label":"$5$"},{"id":"C","label":"$15$"},{"id":"D","label":"$16$"}]}'::jsonb,43,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b7ba0427-02e4-1f4f-0c2d-bb5e4fa107b6','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Since $32 = 2^5$, the exponents must be equal: $x + 1 = 5$, so $x = 4$. Choice B is the value of $x + 1$. Choice D is the value of $2^x$, since $2^{x + 1} = 2 \\cdot 2^x = 32$ gives $2^x = 16$. Choice C treats $2^{x + 1}$ as $2(x + 1)$ and solves $2x + 2 = 32$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b7ba0427-02e4-1f4f-0c2d-bb5e4fa107b6') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1a53218a-d458-156e-133d-478e8637a1b5','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What is the negative solution to the equation $(x + 2)^2 = 25$?","options":[{"id":"A","label":"$-23$"},{"id":"B","label":"$-7$"},{"id":"C","label":"$-3$"},{"id":"D","label":"$3$"}]}'::jsonb,44,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1a53218a-d458-156e-133d-478e8637a1b5','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Take square roots: $x + 2 = 5$ or $x + 2 = -5$. So $x = 3$ or $x = -7$; the negative solution is $-7$. Choice A forgets to take the square root of 25. Choice C solves $x + 2 = -5$ by adding 2 instead of subtracting it. Choice D is the positive solution."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1a53218a-d458-156e-133d-478e8637a1b5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('39054ae5-1a69-a437-f44c-472407a29825','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"What is the real solution to the equation $2x^3 - 54 = 0$?"}'::jsonb,45,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-009","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '39054ae5-1a69-a437-f44c-472407a29825','{"accepted":["3"]}'::jsonb,'{"feedback":{"explanation":"Add 54 and divide by 2: $x^3 = 27$. The real cube root of 27 is 3, since $3^3 = 27$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='39054ae5-1a69-a437-f44c-472407a29825') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('92bf4308-4dd7-8f06-e044-72d4bda2e46f','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"$$y = x^2$$ $$y = 9$$ How many solutions $(x, y)$ does the system of equations have?","options":[{"id":"A","label":"Zero"},{"id":"B","label":"Exactly one"},{"id":"C","label":"Exactly two"},{"id":"D","label":"Infinitely many"}]}'::jsonb,46,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '92bf4308-4dd7-8f06-e044-72d4bda2e46f','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Substitute $y = 9$: $x^2 = 9$, so $x = 3$ or $x = -3$. The solutions are $(3, 9)$ and $(-3, 9)$: exactly two. Choice B counts only the positive square root. Graphically, the horizontal line $y = 9$ crosses the parabola $y = x^2$ twice, so choice A and choice D are not possible."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='92bf4308-4dd7-8f06-e044-72d4bda2e46f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('db454620-657c-31d9-ad6a-2d4e6028b5cd','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"What is the solution to the equation $x^2 - 10x + 25 = 0$?"}'::jsonb,47,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-011","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'db454620-657c-31d9-ad6a-2d4e6028b5cd','{"accepted":["5"]}'::jsonb,'{"feedback":{"explanation":"The left side is a perfect square: $(x - 5)^2 = 0$, so $x - 5 = 0$ and $x = 5$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='db454620-657c-31d9-ad6a-2d4e6028b5cd') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8232669b-d453-6f54-b373-2df1d898b557','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"If $x^2 - x - 12 = 0$ and $x > 0$, what is the value of $x$?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$4$"},{"id":"C","label":"$6$"},{"id":"D","label":"$12$"}]}'::jsonb,48,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8232669b-d453-6f54-b373-2df1d898b557','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Factor: $(x - 4)(x + 3) = 0$, so $x = 4$ or $x = -3$. Since $x > 0$, $x = 4$. Choice A drops the negative sign of the solution $-3$. Choice C and choice D are factors of 12 that do not satisfy the equation; for example, $6^2 - 6 - 12 = 18$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8232669b-d453-6f54-b373-2df1d898b557') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1e787e00-f4c0-76fb-b177-4db064c6279e','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What value of $x$ satisfies $\\sqrt{2x} = 6$?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$12$"},{"id":"C","label":"$18$"},{"id":"D","label":"$36$"}]}'::jsonb,49,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1e787e00-f4c0-76fb-b177-4db064c6279e','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Square both sides: $2x = 36$, so $x = 18$. Choice A divides 6 by 2 without squaring. Choice B doubles 6. Choice D is the value of $2x$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1e787e00-f4c0-76fb-b177-4db064c6279e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('40442e99-4121-cfae-9c0e-56deb9b35104','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What are the solutions to $x^2 - 4x - 1 = 0$?","options":[{"id":"A","label":"$2 \\pm \\sqrt{5}$"},{"id":"B","label":"$2 \\pm \\sqrt{3}$"},{"id":"C","label":"$-2 \\pm \\sqrt{5}$"},{"id":"D","label":"$4 \\pm 2\\sqrt{5}$"}]}'::jsonb,50,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '40442e99-4121-cfae-9c0e-56deb9b35104','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"By the quadratic formula, $x = \\frac{4 \\pm \\sqrt{16 + 4}}{2} = \\frac{4 \\pm 2\\sqrt{5}}{2} = 2 \\pm \\sqrt{5}$. (Completing the square gives the same result: $(x - 2)^2 = 5$.) Choice C uses $-b = -4$ instead of $4$. Choice B subtracts 4 under the radical instead of adding it. Choice D forgets to divide the whole numerator by 2."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='40442e99-4121-cfae-9c0e-56deb9b35104') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('da33924c-7361-1fae-0d33-5ecd0dccc32f','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"$$y = x^2 - 2x$$ $$y = x + 4$$ Which point $(x, y)$ is a solution to the system of equations?","options":[{"id":"A","label":"$(4, 0)$"},{"id":"B","label":"$(4, 8)$"},{"id":"C","label":"$(1, 5)$"},{"id":"D","label":"$(-4, 0)$"}]}'::jsonb,51,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'da33924c-7361-1fae-0d33-5ecd0dccc32f','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Set the expressions equal: $x^2 - 2x = x + 4$, so $x^2 - 3x - 4 = 0$ and $(x - 4)(x + 1) = 0$. If $x = 4$, then $y = 8$; if $x = -1$, then $y = 3$. Only $(4, 8)$ is listed. Choice A has the right $x$-value but the wrong $y$-value, so it lies on neither graph. Choice C lies on the line but not on the parabola. Choice D lies on the line but not on the parabola."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='da33924c-7361-1fae-0d33-5ecd0dccc32f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3c62bd9b-eb7f-19a7-1702-7d36d25d7464','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What are all the solutions to the equation $\\sqrt{2x + 7} = x + 2$?","options":[{"id":"A","label":"$1$ and $-3$"},{"id":"B","label":"$-3$ only"},{"id":"C","label":"$1$ only"},{"id":"D","label":"There is no solution."}]}'::jsonb,52,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '3c62bd9b-eb7f-19a7-1702-7d36d25d7464','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Square both sides: $2x + 7 = x^2 + 4x + 4$, so $x^2 + 2x - 3 = 0$ and $(x + 3)(x - 1) = 0$. Check each value in the original equation: $x = 1$ gives $\\sqrt{9} = 3$, which equals $1 + 2$. But $x = -3$ gives $\\sqrt{1} = 1$, while $-3 + 2 = -1$, so $-3$ is extraneous. Choice A keeps the extraneous solution. Choice B keeps only the extraneous one, and choice D overlooks that $x = 1$ checks."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='3c62bd9b-eb7f-19a7-1702-7d36d25d7464') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e528ac80-e291-7010-8a1b-67e4df3a2293','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"In the equation $x^2 + kx + 9 = 0$, $k$ is a positive constant. If the equation has exactly one real solution, what is the value of $k$?"}'::jsonb,53,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-017","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'e528ac80-e291-7010-8a1b-67e4df3a2293','{"accepted":["6"]}'::jsonb,'{"feedback":{"explanation":"A quadratic has exactly one real solution when its discriminant is 0: $k^2 - 4(1)(9) = 0$, so $k^2 = 36$. Since $k > 0$, $k = 6$. (Then $x^2 + 6x + 9 = (x + 3)^2$.)"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='e528ac80-e291-7010-8a1b-67e4df3a2293') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fd437203-7b0f-deaf-a376-eda0dfba0a30','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What is the sum of the solutions to the equation $\\frac{3}{x - 1} = \\frac{x}{2}$?","options":[{"id":"A","label":"$-1$"},{"id":"B","label":"$1$"},{"id":"C","label":"$5$"},{"id":"D","label":"$6$"}]}'::jsonb,54,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fd437203-7b0f-deaf-a376-eda0dfba0a30','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Cross-multiply: $x(x - 1) = 6$, so $x^2 - x - 6 = 0$ and $(x - 3)(x + 2) = 0$. The solutions are 3 and $-2$ (neither makes a denominator zero), and their sum is 1. Choice A has the wrong sign. Choice C adds 3 and 2, ignoring the negative sign of $-2$. Choice D is the constant that appears after cross-multiplying, not a sum of solutions."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fd437203-7b0f-deaf-a376-eda0dfba0a30') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fab4bb17-8553-46eb-7a2e-6c68712ccbad','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"What value of $x$ satisfies $4^{x} = 8^{x - 1}$?"}'::jsonb,55,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-019","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fab4bb17-8553-46eb-7a2e-6c68712ccbad','{"accepted":["3"]}'::jsonb,'{"feedback":{"explanation":"Write both sides as powers of 2: $4^x = 2^{2x}$ and $8^{x - 1} = 2^{3x - 3}$. Setting the exponents equal gives $2x = 3x - 3$, so $x = 3$. Check: $4^3 = 64$ and $8^2 = 64$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fab4bb17-8553-46eb-7a2e-6c68712ccbad') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fb94cdd0-f7d7-f3c0-8140-637a7f84294d','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"A ball is thrown upward from the roof of a building. Its height, in meters, $t$ seconds after it is thrown is modeled by $h(t) = -4.9t^2 + 19.6t + 24.5$. How many seconds after it is thrown does the ball hit the ground?","options":[{"id":"A","label":"$1$"},{"id":"B","label":"$2$"},{"id":"C","label":"$4$"},{"id":"D","label":"$5$"}]}'::jsonb,56,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fb94cdd0-f7d7-f3c0-8140-637a7f84294d','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Set $h(t) = 0$ and divide by $-4.9$: $t^2 - 4t - 5 = 0$, so $(t - 5)(t + 1) = 0$. Time is positive, so $t = 5$. Choice A drops the negative sign of the rejected solution $-1$. Choice B is the time when the ball reaches its maximum height, $t = \\frac{19.6}{2(4.9)}$. Choice C is the sum of the two solutions of the quadratic."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fb94cdd0-f7d7-f3c0-8140-637a7f84294d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('61b0cb85-83b2-c497-4389-5a9a29b2ad3f','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The equation $x^2 - 10x + c = 0$, where $c$ is a constant, has solutions $x = 3$ and $x = k$. What is the value of $c$?"}'::jsonb,57,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-021","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '61b0cb85-83b2-c497-4389-5a9a29b2ad3f','{"accepted":["21"]}'::jsonb,'{"feedback":{"explanation":"Substitute $x = 3$: $9 - 30 + c = 0$, so $c = 21$. (The other solution is $k = 7$, since $x^2 - 10x + 21 = (x - 3)(x - 7)$.)"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='61b0cb85-83b2-c497-4389-5a9a29b2ad3f') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f0424222-7911-dcd9-0e5d-273e4357da37','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"$$x + y = 7$$ $$xy = 12$$ If $(x, y)$ is a solution to the system of equations, what is the value of $x^2 + y^2$?","options":[{"id":"A","label":"$25$"},{"id":"B","label":"$37$"},{"id":"C","label":"$49$"},{"id":"D","label":"$73$"}]}'::jsonb,58,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f0424222-7911-dcd9-0e5d-273e4357da37','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Square the first equation: $x^2 + 2xy + y^2 = 49$. Substitute $xy = 12$: $x^2 + y^2 = 49 - 24 = 25$. (Indeed, the solutions are $(3, 4)$ and $(4, 3)$.) Choice C assumes $(x + y)^2 = x^2 + y^2$. Choice B subtracts $xy$ instead of $2xy$. Choice D adds $2xy$ instead of subtracting it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f0424222-7911-dcd9-0e5d-273e4357da37') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9a4f6b3c-2610-c9c5-146f-d14c67861e70','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What is the sum of all solutions to the equation $|2x - 5| = 9$?","options":[{"id":"A","label":"$-2$"},{"id":"B","label":"$5$"},{"id":"C","label":"$7$"},{"id":"D","label":"$14$"}]}'::jsonb,59,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '9a4f6b3c-2610-c9c5-146f-d14c67861e70','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Either $2x - 5 = 9$, giving $x = 7$, or $2x - 5 = -9$, giving $x = -2$. The sum is $7 + (-2) = 5$. Choice A and choice C are the individual solutions. Choice D is the value of $2x$ for the positive case, before dividing by 2."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='9a4f6b3c-2610-c9c5-146f-d14c67861e70') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dfb82aa3-f96d-c1c7-f735-39bb9fc8318d','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"How many real solutions does the equation $x^2 + 6x + 13 = 0$ have?","options":[{"id":"A","label":"Zero"},{"id":"B","label":"Exactly one"},{"id":"C","label":"Exactly two"},{"id":"D","label":"Infinitely many"}]}'::jsonb,60,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-024","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'dfb82aa3-f96d-c1c7-f735-39bb9fc8318d','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The discriminant is $6^2 - 4(1)(13) = 36 - 52 = -16$. A negative discriminant means there are no real solutions. (Completing the square gives $(x + 3)^2 = -4$, and a square cannot be negative.) Choice B would require a discriminant of 0, and choice C a positive discriminant. A quadratic equation never has infinitely many solutions (choice D)."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='dfb82aa3-f96d-c1c7-f735-39bb9fc8318d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f5bedf65-a35a-39e8-6bb8-b1e4c143f7b2','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"A rectangular garden has a length that is 4 meters greater than its width. The area of the garden is 96 square meters. What is the width of the garden, in meters?"}'::jsonb,61,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-025","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f5bedf65-a35a-39e8-6bb8-b1e4c143f7b2','{"accepted":["8"]}'::jsonb,'{"feedback":{"explanation":"Let $w$ be the width. Then $w(w + 4) = 96$, so $w^2 + 4w - 96 = 0$ and $(w + 12)(w - 8) = 0$. A width must be positive, so $w = 8$ (and the length is 12)."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f5bedf65-a35a-39e8-6bb8-b1e4c143f7b2') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('acd67385-81ae-2b81-c018-c11d3dab1fc5','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The solutions to $x^2 - 5x = 14$ are $a$ and $b$, where $a > b$. What is the value of $a - b$?","options":[{"id":"A","label":"$5$"},{"id":"B","label":"$7$"},{"id":"C","label":"$9$"},{"id":"D","label":"$14$"}]}'::jsonb,62,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-026","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'acd67385-81ae-2b81-c018-c11d3dab1fc5','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Rewrite as $x^2 - 5x - 14 = 0$ and factor: $(x - 7)(x + 2) = 0$. So $a = 7$ and $b = -2$, and $a - b = 7 - (-2) = 9$. Choice A computes $7 - 2$, ignoring the sign of $b$ (it is also the sum of the solutions). Choice B is $a$ alone. Choice D is the constant on the right side."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='acd67385-81ae-2b81-c018-c11d3dab1fc5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8b4132b5-afd1-f840-3b1b-47548a2c1f0c','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What are all the solutions to the equation $\\frac{x^2 - 4}{x + 2} = 6$?","options":[{"id":"A","label":"$4$ only"},{"id":"B","label":"$-2$ only"},{"id":"C","label":"$8$ and $-2$"},{"id":"D","label":"$8$ only"}]}'::jsonb,63,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-027","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '8b4132b5-afd1-f840-3b1b-47548a2c1f0c','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Multiply both sides by $x + 2$: $x^2 - 4 = 6x + 12$, so $x^2 - 6x - 16 = 0$ and $(x - 8)(x + 2) = 0$. But $x = -2$ makes the denominator 0, so it is not a solution; only $x = 8$ works. Choice B and choice C include the excluded value. Choice A simplifies the fraction to $x + 2$ instead of $x - 2$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='8b4132b5-afd1-f840-3b1b-47548a2c1f0c') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bb0428c4-789b-9d12-ba01-69d3a3f5ee77','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"$$x^2 + y^2 = 25$$ $$y = x + 1$$ Which point $(x, y)$ is a solution to the system of equations?","options":[{"id":"A","label":"$(3, 4)$"},{"id":"B","label":"$(0, 1)$"},{"id":"C","label":"$(-3, -2)$"},{"id":"D","label":"$(4, 3)$"}]}'::jsonb,64,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-028","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'bb0428c4-789b-9d12-ba01-69d3a3f5ee77','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Substitute $y = x + 1$: $x^2 + (x + 1)^2 = 25$, so $2x^2 + 2x - 24 = 0$, $x^2 + x - 12 = 0$, and $x = 3$ or $x = -4$. The solutions are $(3, 4)$ and $(-4, -3)$, and only $(3, 4)$ is listed. Choice D is on the circle but not on the line. Choice B and choice C are on the line but not on the circle."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='bb0428c4-789b-9d12-ba01-69d3a3f5ee77') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('414bc108-302a-23ec-4878-d4ee611ba72d','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"In the xy-plane, the graphs of $y = x^2 + 3x - 2$ and $y = 5x + k$, where $k$ is a constant, intersect at exactly one point. What is the value of $k$?"}'::jsonb,65,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-029","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '414bc108-302a-23ec-4878-d4ee611ba72d','{"accepted":["-3"]}'::jsonb,'{"feedback":{"explanation":"Set the expressions equal: $x^2 + 3x - 2 = 5x + k$, so $x^2 - 2x - (2 + k) = 0$. Exactly one intersection means the discriminant is 0: $(-2)^2 + 4(2 + k) = 0$, so $4 + 8 + 4k = 0$ and $k = -3$. (The line is tangent to the parabola at $(1, 2)$.)"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='414bc108-302a-23ec-4878-d4ee611ba72d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ae3c0df1-6340-c0de-77d5-a683554cbd96','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What is the sum of all solutions to the equation $\\frac{2}{x} + \\frac{3}{x + 2} = 1$?","options":[{"id":"A","label":"$-4$"},{"id":"B","label":"$-1$"},{"id":"C","label":"$3$"},{"id":"D","label":"$4$"}]}'::jsonb,66,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-030","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ae3c0df1-6340-c0de-77d5-a683554cbd96','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Multiply by $x(x + 2)$: $2(x + 2) + 3x = x(x + 2)$, so $5x + 4 = x^2 + 2x$ and $x^2 - 3x - 4 = 0$. Then $(x - 4)(x + 1) = 0$, giving $x = 4$ or $x = -1$; neither makes a denominator 0. The sum is 3. Choice A is the product of the solutions. Choice B and choice D are the individual solutions."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ae3c0df1-6340-c0de-77d5-a683554cbd96') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4958dfb8-1a25-1b4c-aa9a-576d6b474b40','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"In the equation $2x^2 - 8x + c = 0$, $c$ is a constant. Which of the following describes all values of $c$ for which the equation has two distinct real solutions?","options":[{"id":"A","label":"$c < 4$"},{"id":"B","label":"$c < 8$"},{"id":"C","label":"$c > 8$"},{"id":"D","label":"$c < 16$"}]}'::jsonb,67,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-031","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4958dfb8-1a25-1b4c-aa9a-576d6b474b40','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Two distinct real solutions require a positive discriminant: $(-8)^2 - 4(2)(c) > 0$, so $64 - 8c > 0$ and $c < 8$. Choice C reverses the inequality, which gives no real solutions. Choice D forgets the leading coefficient 2 and uses $64 - 4c > 0$. Choice A is too restrictive; for example, $c = 6$ gives $2x^2 - 8x + 6 = 2(x - 1)(x - 3)$, which has two solutions."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4958dfb8-1a25-1b4c-aa9a-576d6b474b40') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('865a2d6e-21ab-6242-8713-170a694a94ce','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"What is the product of all real solutions to the equation $x^4 - 3x^2 - 4 = 0$?"}'::jsonb,68,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-032","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '865a2d6e-21ab-6242-8713-170a694a94ce','{"accepted":["-4"]}'::jsonb,'{"feedback":{"explanation":"Treat the equation as a quadratic in $x^2$: $(x^2 - 4)(x^2 + 1) = 0$. The factor $x^2 + 1$ is never 0 for real $x$, so the only real solutions come from $x^2 = 4$: $x = 2$ and $x = -2$. Their product is $2 \\cdot (-2) = -4$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='865a2d6e-21ab-6242-8713-170a694a94ce') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0987fc02-cdcd-4550-1c17-09f492f4f73d','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"What is the solution to the equation $x - \\sqrt{x} = 12$?"}'::jsonb,69,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-033","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0987fc02-cdcd-4550-1c17-09f492f4f73d','{"accepted":["16"]}'::jsonb,'{"feedback":{"explanation":"Let $u = \\sqrt{x}$, so $x = u^2$ and $u^2 - u - 12 = 0$. Then $(u - 4)(u + 3) = 0$. Since $u = \\sqrt{x}$ cannot be negative, $u = 4$, so $x = 16$. Check: $16 - 4 = 12$. The value $u = -3$ would give $x = 9$, but $9 - 3 = 6$, so 9 is not a solution."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0987fc02-cdcd-4550-1c17-09f492f4f73d') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1eb459a5-960f-0dab-5fac-ea7ddde9672b','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"In the equation $ax^2 + 4x - 3 = 0$, $a$ is a nonzero constant. If the equation has exactly one real solution, what is the value of $a$?","options":[{"id":"A","label":"$-\\frac{4}{3}$"},{"id":"B","label":"$-\\frac{3}{4}$"},{"id":"C","label":"$\\frac{3}{4}$"},{"id":"D","label":"$\\frac{4}{3}$"}]}'::jsonb,70,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-034","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1eb459a5-960f-0dab-5fac-ea7ddde9672b','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"With $a \\neq 0$, the equation is quadratic, and exactly one solution means the discriminant is 0: $4^2 - 4(a)(-3) = 16 + 12a = 0$, so $a = -\\frac{4}{3}$. Choice D drops the negative sign that comes from $c = -3$. Choice B and choice C invert the ratio $\\frac{16}{12}$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1eb459a5-960f-0dab-5fac-ea7ddde9672b') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b7b8f0d2-b4b9-43d3-e8a3-fc0104a4dad8','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"A company''s monthly profit $P$, in dollars, from selling a gadget at a price of $x$ dollars is modeled by $P(x) = -2x^2 + 160x - 2{,}400$. The company breaks even (makes a profit of 0 dollars) at two prices. What is the greater of these two prices, in dollars?"}'::jsonb,71,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-035","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'b7b8f0d2-b4b9-43d3-e8a3-fc0104a4dad8','{"accepted":["60"]}'::jsonb,'{"feedback":{"explanation":"Set $P(x) = 0$ and divide by $-2$: $x^2 - 80x + 1{,}200 = 0$. Factor: $(x - 20)(x - 60) = 0$, so the break-even prices are 20 and 60 dollars. The greater price is 60. (The price that maximizes profit, 40 dollars, lies halfway between them.)"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='b7b8f0d2-b4b9-43d3-e8a3-fc0104a4dad8') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7eb15137-f73f-39a7-3646-72172ae182ca','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"$$y = 2^x$$ $$y = 8 \\cdot 4^{x - 2}$$ Which point $(x, y)$ is the solution to the system of equations?","options":[{"id":"A","label":"$(2, 4)$"},{"id":"B","label":"$(3, 8)$"},{"id":"C","label":"$(1, 2)$"},{"id":"D","label":"$(-1, \\frac{1}{2})$"}]}'::jsonb,72,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-036","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '7eb15137-f73f-39a7-3646-72172ae182ca','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Write the second equation in base 2: $8 \\cdot 4^{x - 2} = 2^3 \\cdot 2^{2x - 4} = 2^{2x - 1}$. Setting $2^x = 2^{2x - 1}$ gives $x = 2x - 1$, so $x = 1$ and $y = 2^1 = 2$. Choice A, choice B and choice D lie on $y = 2^x$, but for those $x$-values the second equation gives $y = 8$, $32$ and $\\frac{1}{8}$, respectively."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='7eb15137-f73f-39a7-3646-72172ae182ca') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f074cf95-ba4e-c7a1-5ec2-c2839fb87742','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"What are all the solutions to the equation $\\frac{x}{x - 2} = \\frac{2}{x - 2} + 3$?","options":[{"id":"A","label":"$2$ only"},{"id":"B","label":"$0$ only"},{"id":"C","label":"$4$ only"},{"id":"D","label":"There is no solution."}]}'::jsonb,73,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_equations_and_systems","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nleq-037","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f074cf95-ba4e-c7a1-5ec2-c2839fb87742','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Multiply both sides by $x - 2$: $x = 2 + 3(x - 2) = 3x - 4$, so $x = 2$. But $x = 2$ makes the denominators 0, so it is excluded, and the equation has no solution. Choice A ignores the excluded value. Choice B comes from writing $3(x - 2)$ as $3x - 2$, and choice C from treating $\\frac{2}{x - 2}$ as $-\\frac{2}{x - 2}$; neither value satisfies the original equation."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f074cf95-ba4e-c7a1-5ec2-c2839fb87742') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('78853dc1-4dd5-7a15-6687-2ba2086c4559','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The function $f$ is defined by $f(x) = x^2 - 3x + 2$. What is the value of $f(4)$?","options":[{"id":"A","label":"$-2$"},{"id":"B","label":"$6$"},{"id":"C","label":"$18$"},{"id":"D","label":"$30$"}]}'::jsonb,74,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '78853dc1-4dd5-7a15-6687-2ba2086c4559','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"$f(4) = 4^2 - 3(4) + 2 = 16 - 12 + 2 = 6$. Choice A evaluates $4^2$ as 8. Choice C leaves out the $-3x$ term. Choice D adds $3x$ instead of subtracting it."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='78853dc1-4dd5-7a15-6687-2ba2086c4559') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7d611589-bca6-2e4f-a47d-84ea2438efea','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The function $g$ is defined by $g(x) = 3 \\cdot 2^x$. What is the value of $g(3)$?"}'::jsonb,75,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '7d611589-bca6-2e4f-a47d-84ea2438efea','{"accepted":["24"]}'::jsonb,'{"feedback":{"explanation":"$g(3) = 3 \\cdot 2^3 = 3 \\cdot 8 = 24$. Note that the exponent applies only to 2: computing $6^3 = 216$ would be an error."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='7d611589-bca6-2e4f-a47d-84ea2438efea') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a42f6126-84c5-5d4a-a945-bac8e4022950','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The population of a town $t$ years after 2020 is modeled by $P(t) = 500(1.04)^t$. What is the best interpretation of 500 in this context?","options":[{"id":"A","label":"The estimated population of the town in 2020"},{"id":"B","label":"The population increases by 500 people each year."},{"id":"C","label":"The population increases by 500% each year."},{"id":"D","label":"The estimated population of the town after 4 years"}]}'::jsonb,76,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'a42f6126-84c5-5d4a-a945-bac8e4022950','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"When $t = 0$ (the year 2020), $P(0) = 500(1.04)^0 = 500$, so 500 is the population in 2020. Choice B describes linear growth; this model grows by 4% each year, a different number of people every year. Choice C misreads the growth rate, which is given by 1.04, not 500. Choice D confuses the 4 in 1.04 with a number of years."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='a42f6126-84c5-5d4a-a945-bac8e4022950') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bab47b5b-53e0-0fa1-9ecd-9e2005ffa9a7','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"In the xy-plane, what is the y-intercept of the graph of $y = (x - 2)(x + 5)$?","options":[{"id":"A","label":"$(0, 10)$"},{"id":"B","label":"$(0, -10)$"},{"id":"C","label":"$(2, 0)$"},{"id":"D","label":"$(0, 3)$"}]}'::jsonb,77,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'bab47b5b-53e0-0fa1-9ecd-9e2005ffa9a7','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Set $x = 0$: $y = (0 - 2)(0 + 5) = -10$, so the y-intercept is $(0, -10)$. Choice A loses the negative sign. Choice C is an x-intercept. Choice D adds $-2$ and 5 instead of multiplying them."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='bab47b5b-53e0-0fa1-9ecd-9e2005ffa9a7') on conflict do nothing;
