insert into public.answer_keys(content_unit_id,correct,metadata) select '4a88bc00-c463-d988-9fec-27ba5cc91c80','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The minimum value of $f(x)$ is the y-coordinate of the vertex, the lowest point of the graph: $-1$. Choice C is the x-coordinate of the vertex, which is where the minimum occurs, not the minimum value. Choice B and choice D are x-intercepts."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4a88bc00-c463-d988-9fec-27ba5cc91c80') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('782c3014-93c7-34df-9814-b1938e79a73a','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The function $f$ is defined by $f(x) = 2x^2 + 1$. What is the value of $f(-3)$?","options":[{"id":"A","label":"$-17$"},{"id":"B","label":"$13$"},{"id":"C","label":"$19$"},{"id":"D","label":"$37$"}]}'::jsonb,79,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '782c3014-93c7-34df-9814-b1938e79a73a','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"$f(-3) = 2(-3)^2 + 1 = 2(9) + 1 = 19$. Choice A computes $(-3)^2$ as $-9$. Choice B treats squaring as doubling, $2 \\cdot 2 \\cdot 3 + 1$. Choice D squares $2 \\cdot (-3)$ instead of squaring only $-3$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='782c3014-93c7-34df-9814-b1938e79a73a') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('639a2a75-ddf3-17e0-3ee3-2c421829d01e','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The function $g$ is defined by $g(x) = (x - 4)(x + 1)(x - 7)$. What are the zeros of $g$?","options":[{"id":"A","label":"$-4$, $1$, and $-7$"},{"id":"B","label":"$4$, $1$, and $7$"},{"id":"C","label":"$4$, $-1$, and $7$"},{"id":"D","label":"$28$ only"}]}'::jsonb,80,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '639a2a75-ddf3-17e0-3ee3-2c421829d01e','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Each factor equals 0 at one value: $x - 4 = 0$ at $x = 4$, $x + 1 = 0$ at $x = -1$, and $x - 7 = 0$ at $x = 7$. Choice A reverses every sign. Choice B reverses the sign of the zero from $x + 1$. Choice D multiplies the constants, which gives $g(0) = 28$, not a zero."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='639a2a75-ddf3-17e0-3ee3-2c421829d01e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('18fc766d-fc77-2ee6-de8a-b4e5398e02c5','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The value, in dollars, of a car $t$ years after it is purchased is modeled by $V(t) = 24{,}000(0.85)^t$. According to the model, by what percent does the car''s value decrease each year?","options":[{"id":"A","label":"0.85%"},{"id":"B","label":"8.5%"},{"id":"C","label":"15%"},{"id":"D","label":"85%"}]}'::jsonb,81,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '18fc766d-fc77-2ee6-de8a-b4e5398e02c5','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Each year the value is multiplied by 0.85, so it keeps 85% of its value and loses $100\\% - 85\\% = 15\\%$. Choice D is the percent of the value that remains, not the percent lost. Choice A and choice B misplace the decimal point."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='18fc766d-fc77-2ee6-de8a-b4e5398e02c5') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fe75a0c2-ea8f-634d-0284-d0a807f6787e','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The table shows four values of $x$ and the corresponding values of $f(x)$ for a function $f$. Which equation could define $f$?","table":{"headers":["x","f(x)"],"rows":[["0","3"],["1","6"],["2","12"],["3","24"]]},"options":[{"id":"A","label":"$f(x) = 3x + 3$"},{"id":"B","label":"$f(x) = 2(3)^x$"},{"id":"C","label":"$f(x) = 6x$"},{"id":"D","label":"$f(x) = 3(2)^x$"}]}'::jsonb,82,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'fe75a0c2-ea8f-634d-0284-d0a807f6787e','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Each time $x$ increases by 1, $f(x)$ doubles, and $f(0) = 3$. So $f(x) = 3(2)^x$. Choice A fits the first two rows only ($f(2)$ would be 9). Choice B swaps the initial value and the growth factor, giving $f(0) = 2$. Choice C gives $f(0) = 0$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='fe75a0c2-ea8f-634d-0284-d0a807f6787e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0745f8ce-aec4-22ec-93dc-15e2afba3ec1','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"In the xy-plane, what is the vertex of the graph of $y = (x + 3)^2 - 4$?","options":[{"id":"A","label":"$(-3, -4)$"},{"id":"B","label":"$(3, -4)$"},{"id":"C","label":"$(-3, 4)$"},{"id":"D","label":"$(3, 4)$"}]}'::jsonb,83,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0745f8ce-aec4-22ec-93dc-15e2afba3ec1','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"In vertex form $y = (x - h)^2 + k$, the vertex is $(h, k)$. Here $x + 3 = x - (-3)$, so $h = -3$ and $k = -4$: the vertex is $(-3, -4)$. Choice B misreads the sign of $h$. Choice C and choice D misread the sign of $k$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0745f8ce-aec4-22ec-93dc-15e2afba3ec1') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('661b2672-6289-79f5-1d8d-e056a05ea278','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The function $h$ is defined by $h(x) = x^3 - 2x$. What is the value of $h(-2)$?","options":[{"id":"A","label":"$-12$"},{"id":"B","label":"$-4$"},{"id":"C","label":"$4$"},{"id":"D","label":"$12$"}]}'::jsonb,84,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '661b2672-6289-79f5-1d8d-e056a05ea278','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"$h(-2) = (-2)^3 - 2(-2) = -8 + 4 = -4$. Choice A subtracts 4 instead of adding it (the product $-2(-2)$ is positive). Choice C treats $(-2)^3$ as $+8$. Choice D makes both sign errors."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='661b2672-6289-79f5-1d8d-e056a05ea278') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('00817daa-b044-b3f3-463c-2c53594ac856','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"A bacteria culture starts with 200 cells, and the number of cells doubles every 3 hours. Which function gives the number of cells $N(t)$ after $t$ hours?","options":[{"id":"A","label":"$N(t) = 200(2)^{3t}$"},{"id":"B","label":"$N(t) = 200(2)^{\\frac{t}{3}}$"},{"id":"C","label":"$N(t) = 200(3)^{\\frac{t}{2}}$"},{"id":"D","label":"$N(t) = 200 + 2^{\\frac{t}{3}}$"}]}'::jsonb,85,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '00817daa-b044-b3f3-463c-2c53594ac856','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The number of doublings after $t$ hours is $\\frac{t}{3}$, so $N(t) = 200(2)^{\\frac{t}{3}}$. Check: $N(3) = 400$ and $N(6) = 800$. Choice A doubles three times every hour. Choice C swaps the growth factor and the doubling time. Choice D adds instead of multiplying, so $N(3)$ would be only 202."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='00817daa-b044-b3f3-463c-2c53594ac856') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4434d152-cfc2-84a0-40c3-9c8a78dae097','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"For what value of $x$ is the function $f(x) = \\frac{x + 1}{x - 4}$ undefined?","options":[{"id":"A","label":"$-4$"},{"id":"B","label":"$-1$"},{"id":"C","label":"$1$"},{"id":"D","label":"$4$"}]}'::jsonb,86,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '4434d152-cfc2-84a0-40c3-9c8a78dae097','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"A fraction is undefined when its denominator is 0: $x - 4 = 0$ when $x = 4$. Choice A has the wrong sign. Choice B is the zero of $f$ (where the numerator is 0), and $f(-1) = 0$ is defined. Choice C reverses the sign of that zero."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='4434d152-cfc2-84a0-40c3-9c8a78dae097') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('674d952f-fe24-80ed-4dce-dad53488bcd6','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The function $f$ is defined by $f(x) = x^2 - 8x + 15$. What is the minimum value of $f(x)$?","options":[{"id":"A","label":"$-16$"},{"id":"B","label":"$-1$"},{"id":"C","label":"$4$"},{"id":"D","label":"$15$"}]}'::jsonb,87,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '674d952f-fe24-80ed-4dce-dad53488bcd6','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The vertex is at $x = -\\frac{-8}{2(1)} = 4$, and $f(4) = 16 - 32 + 15 = -1$. Equivalently, $f(x) = (x - 4)^2 - 1$. Choice A completes the square but forgets to add the 15. Choice C is the $x$-value where the minimum occurs. Choice D is $f(0)$, the y-intercept."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='674d952f-fe24-80ed-4dce-dad53488bcd6') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ac0fec3e-8a3b-1f1d-af29-c0a44c6b96ed','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The functions $f$ and $g$ are defined by $f(x) = 2x + 1$ and $g(x) = x^2 - 3$. What is the value of $f(g(2))$?"}'::jsonb,88,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-015","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'ac0fec3e-8a3b-1f1d-af29-c0a44c6b96ed','{"accepted":["3"]}'::jsonb,'{"feedback":{"explanation":"Work from the inside out: $g(2) = 4 - 3 = 1$. Then $f(1) = 2(1) + 1 = 3$. Computing $g(f(2)) = g(5) = 22$ instead reverses the order of the functions."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='ac0fec3e-8a3b-1f1d-af29-c0a44c6b96ed') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c0d3cd5c-964b-51ae-2bb1-f04681130b2f','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"A museum had 1,200 members at the end of 2023. The number of members is expected to increase by 5% each year. Which function gives the expected number of members $M(t)$, $t$ years after the end of 2023?","options":[{"id":"A","label":"$M(t) = 1{,}200(0.05)^t$"},{"id":"B","label":"$M(t) = 1{,}200(1.5)^t$"},{"id":"C","label":"$M(t) = 1{,}200(1.05)^t$"},{"id":"D","label":"$M(t) = 1{,}200 + 0.05t$"}]}'::jsonb,89,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'c0d3cd5c-964b-51ae-2bb1-f04681130b2f','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Increasing by 5% means multiplying by $1 + 0.05 = 1.05$ each year, so $M(t) = 1{,}200(1.05)^t$. Choice A would multiply by 0.05, keeping only 5% of the members each year. Choice B uses 1.5, which is a 50% increase. Choice D adds 0.05 member per year, a linear model."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='c0d3cd5c-964b-51ae-2bb1-f04681130b2f') on conflict do nothing;
