insert into public.answer_keys(content_unit_id,correct,metadata) select '441b8b67-d01d-6e83-1471-f71b157cb9f8','{"accepted":["-12"]}'::jsonb,'{"feedback":{"explanation":"From the x-intercepts, $f(x) = a(x + 3)(x - 1)$. Since $f(0) = 3$, $a(3)(-1) = 3$, so $a = -1$. Then $f(3) = -(3 + 3)(3 - 1) = -12$. (In vertex form, $f(x) = -(x + 1)^2 + 4$.)"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='441b8b67-d01d-6e83-1471-f71b157cb9f8') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5bdd5c49-9ec9-8680-ef59-415a6f4ab032','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"The function $f$ is defined by $f(x) = (x - k)(x + 6)$, where $k$ is a constant. The graph of $y = f(x)$ in the xy-plane is symmetric about the line $x = -1$. What is the value of $k$?"}'::jsonb,105,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-032","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '5bdd5c49-9ec9-8680-ef59-415a6f4ab032','{"accepted":["4"]}'::jsonb,'{"feedback":{"explanation":"The zeros of $f$ are $k$ and $-6$, and the axis of symmetry lies halfway between them: $\\frac{k + (-6)}{2} = -1$. So $k - 6 = -2$ and $k = 4$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='5bdd5c49-9ec9-8680-ef59-415a6f4ab032') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('03e2949d-5efb-a217-045d-52d93591b416','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The function $g$ is defined by $g(x) = \\frac{2x - 6}{x^2 - 9}$. Which of the following gives all the vertical asymptotes of the graph of $y = g(x)$ in the xy-plane?","options":[{"id":"A","label":"$x = 3$ only"},{"id":"B","label":"$x = -3$ and $x = 3$"},{"id":"C","label":"$x = -3$ only"},{"id":"D","label":"$x = 9$ only"}]}'::jsonb,106,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-033","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '03e2949d-5efb-a217-045d-52d93591b416','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Factor: $g(x) = \\frac{2(x - 3)}{(x - 3)(x + 3)} = \\frac{2}{x + 3}$ for $x \\neq 3$. At $x = -3$ the denominator is 0 but the numerator is not, so there is a vertical asymptote. At $x = 3$ the common factor cancels, so the graph has a hole at $\\left(3, \\frac{1}{3}\\right)$, not an asymptote. Choice B overlooks the cancellation. Choice A keeps the hole and drops the asymptote. Choice D sets $x^2$ equal to 9 incorrectly as $x = 9$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='03e2949d-5efb-a217-045d-52d93591b416') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1d0402dc-f016-098d-b9a2-0fdc16a4265e','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The function $p$ is defined by $p(x) = x^3 - 4x^2 - 7x + 10$, and $p(1) = 0$. What is the greatest zero of $p$?","options":[{"id":"A","label":"$1$"},{"id":"B","label":"$2$"},{"id":"C","label":"$5$"},{"id":"D","label":"$10$"}]}'::jsonb,107,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-034","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '1d0402dc-f016-098d-b9a2-0fdc16a4265e','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Since $p(1) = 0$, $x - 1$ is a factor. Dividing gives $p(x) = (x - 1)(x^2 - 3x - 10) = (x - 1)(x - 5)(x + 2)$. The zeros are 1, 5, and $-2$, so the greatest is 5. Choice A is the given zero. Choice B reverses the sign of the zero $-2$. Choice D is the constant term."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='1d0402dc-f016-098d-b9a2-0fdc16a4265e') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0470b27f-b458-89f5-0b21-4d9d4b534268','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"A farmer uses 120 meters of fencing to make a rectangular pen along a straight wall, so fencing is needed on only three sides. If each side perpendicular to the wall has length $x$ meters, the area of the pen, in square meters, is $A(x) = x(120 - 2x)$. What is the maximum possible area of the pen, in square meters?"}'::jsonb,108,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-035","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0470b27f-b458-89f5-0b21-4d9d4b534268','{"accepted":["1800"]}'::jsonb,'{"feedback":{"explanation":"$A(x) = -2x^2 + 120x$ is a downward-opening parabola with zeros at $x = 0$ and $x = 60$. Its maximum is halfway between them, at $x = 30$: $A(30) = 30(120 - 60) = 1{,}800$. (A common error is to report the side length 30 or 60 instead of the area.)"},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0470b27f-b458-89f5-0b21-4d9d4b534268') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f34eacfe-ca83-d4a4-a0c9-5f65cc291b43','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_single_choice','{"prompt":"The function $f$ is defined by $f(x) = c \\cdot b^x$, where $c$ and $b$ are positive constants. If $f(1) = 6$ and $f(3) = 54$, what is the value of $f(0)$?","options":[{"id":"A","label":"$2$"},{"id":"B","label":"$3$"},{"id":"C","label":"$6$"},{"id":"D","label":"$18$"}]}'::jsonb,109,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-036","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select 'f34eacfe-ca83-d4a4-a0c9-5f65cc291b43','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Divide: $\\frac{f(3)}{f(1)} = \\frac{cb^3}{cb} = b^2 = \\frac{54}{6} = 9$, so $b = 3$. Then $f(1) = 3c = 6$ gives $c = 2$, and $f(0) = c = 2$. Choice B is the base $b$. Choice C is $f(1)$. Choice D is $f(2)$."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='f34eacfe-ca83-d4a4-a0c9-5f65cc291b43') on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0c8478e4-9925-ce71-c59f-4e80e266c3f0','20dc549c-274c-938f-fb11-e72eb65b2a6e','question_spr','{"prompt":"For the polynomial $p(x) = 2x^3 + kx^2 - 5x + 6$, where $k$ is a constant, $x + 3$ is a factor of $p(x)$. What is the value of $k$?"}'::jsonb,110,'{"section_type":"math","sat_domain":"advanced_math","sat_official_domain":"advanced_math","sat_skill":"nonlinear_functions","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"adv-nlfn-037","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) select '0c8478e4-9925-ce71-c59f-4e80e266c3f0','{"accepted":["11/3","3.666","3.667"]}'::jsonb,'{"feedback":{"explanation":"If $x + 3$ is a factor, then $p(-3) = 0$: $2(-27) + 9k + 15 + 6 = 0$, so $9k - 33 = 0$ and $k = \\frac{11}{3}$. Enter 11/3, 3.666, or 3.667."},"source":"original-schood-practice-v2"}'::jsonb where exists(select 1 from public.content_units where id='0c8478e4-9925-ce71-c59f-4e80e266c3f0') on conflict do nothing;
